-- FYRELITH | Stay in the current server
-- Blocks the game's idle rejoin request before it reaches the server.
-- A server shutdown or a server-initiated teleport cannot be cancelled here.
do
 local environment=type(getgenv)=='function' and getgenv() or _G
 local guard=environment.FyrelithStayServer
 if not guard then guard={Enabled=true,Blocked=0,Ready=false} environment.FyrelithStayServer=guard end
 guard.Enabled=true
 local RS=game:GetService('ReplicatedStorage')
 local teleport=game:GetService('TeleportService')
 local methods={teleport=true,teleporttoplaceinstance=true,teleporttoprivateserver=true,teleportasync=true,teleportpartyasync=true}
 function guard.ShouldBlock(target,method)
  if not guard.Enabled then return false end
  method=string.lower(tostring(method))
  if target==teleport and methods[method] then return true end
  if method=='fireserver' and typeof(target)=='Instance' and target.Name=='RejoinRemote' then
   local parent=target.Parent
   return parent~=nil and parent.Name=='Remotes' and parent.Parent==RS
  end
  return false
 end
 if not guard.Ready then
  if type(hookmetamethod)=='function' and type(getnamecallmethod)=='function' and type(newcclosure)=='function' then
   local previous
   local ok,result=pcall(function()
    previous=hookmetamethod(game,'__namecall',newcclosure(function(target,...)
     local method=getnamecallmethod()
     if guard.ShouldBlock(target,method) then
      guard.Blocked+=1 guard.LastBlockedMethod=method guard.LastBlockedAt=os.clock()
      return nil
     end
     return previous(target,...)
    end))
   end)
   guard.Ready=ok
   guard.LastError=not ok and tostring(result) or nil
  else guard.LastError='Executor does not support the server-transfer guard' end
 end
end

-- FYRELITH | Standalone Anti AFK v2
-- Fixed heartbeat; independent of farm activity, focus events and UI lifetime.
do
 local environment=type(getgenv)=='function' and getgenv() or _G
 local player=game:GetService('Players').LocalPlayer
 while not player do task.wait(.1) player=game:GetService('Players').LocalPlayer end
 local previous=environment.FyrelithAntiAFK
 if not (previous and previous.Version==2 and previous.Alive and previous.Player==player and previous.IdledConnection and previous.IdledConnection.Connected) then
  if previous and previous.Cleanup then pcall(previous.Cleanup) end
  local virtualUser=game:GetService('VirtualUser')
  local anti={Version=2,Alive=true,Player=player,Pulses=0,LastPulse=-math.huge,LastAttempt=-math.huge,Busy=false,Connections={},DisabledIdleConnections={},Errors={}}
  environment.FyrelithAntiAFK=anti
  local disabled=setmetatable({},{__mode='k'})
  function anti.ProtectIdle()
   if not anti.Alive or type(getconnections)~='function' then return end
   local ok,list=pcall(getconnections,player.Idled)
   if not ok then return end
   for _,connection in list do
    if connection~=anti.IdledConnection and not disabled[connection] and connection.Enabled==true and connection.ForeignState~=true then
     local callback=connection.Function
     local native=connection.LuaConnection==false
     if not native and type(callback)=='function' and type(isexecutorclosure)=='function' then
      local checked,executor=pcall(isexecutorclosure,callback)
      native=checked and not executor
     end
     if native then
      local stopped=pcall(function()connection:Disable()end)
      if stopped then disabled[connection]=true table.insert(anti.DisabledIdleConnections,connection) end
     end
    end
   end
  end
  function anti.Pulse()
   if not anti.Alive or anti.Busy or os.clock()-anti.LastAttempt<20 then return false end
   anti.Busy=true anti.LastAttempt=os.clock()
   local camera=workspace.CurrentCamera local frame=camera and camera.CFrame or CFrame.new()
   local userOK,userError=pcall(function()
    virtualUser:CaptureController()
    virtualUser:Button2Down(Vector2.zero,frame)
    task.wait(.05)
    virtualUser:Button2Up(Vector2.zero,frame)
   end)
   if not userOK then pcall(virtualUser.Button2Up,virtualUser,Vector2.zero,frame) end
   -- An unused function key provides a second input path without moving the character.
   local key=Enum.KeyCode.F15
   local manager=game:GetService('VirtualInputManager')
   local keyOK,keyError=pcall(function()
    manager:SendKeyEvent(true,key,false,game)
    manager:SendKeyEvent(false,key,false,game)
   end)
   if not keyOK then pcall(manager.SendKeyEvent,manager,false,key,false,game) end
   anti.Errors.VirtualUser=not userOK and tostring(userError) or nil
   anti.Errors.VirtualInputManager=not keyOK and tostring(keyError) or nil
   local ok=userOK or keyOK
   anti.Method=userOK and keyOK and 'VirtualUser + VirtualInputManager' or userOK and 'VirtualUser' or keyOK and 'VirtualInputManager' or 'Idle listener protection'
   if ok then anti.Pulses+=1 anti.LastPulse=os.clock() anti.LastError=nil
   else anti.LastError='Input unavailable: '..tostring(userError)..' / '..tostring(keyError) end
   anti.Busy=false
   return ok
  end
  anti.IdledConnection=player.Idled:Connect(function()task.spawn(anti.Pulse)end)
  table.insert(anti.Connections,anti.IdledConnection)
  function anti.Cleanup()
   if not anti.Alive then return end
   anti.Alive=false
   for _,connection in anti.Connections do connection:Disconnect() end
   for _,connection in anti.DisabledIdleConnections do pcall(function()connection:Enable()end) end
  end
  anti.ProtectIdle()
  task.spawn(function()
   while anti.Alive and player.Parent do
    anti.ProtectIdle()
    if os.clock()-anti.LastAttempt>=60 then anti.Pulse() end
    task.wait(5)
   end
   anti.Cleanup()
  end)
 end
end

