S.tryUseOptInPotion=function(key,name)
 local allowed={luckPotion="LuckPotion",cashPotion="CashPotion",speedPotion="GradeSpeedPotion",bluetooth="BluetoothPotion"}
 if G.BlueFarm~=S or not S.running or not S.enabled or allowed[key]~=name or X[key]~=true or S.potionConsent[key]~=true then return false end
 R.UseItem:FireServer(name)
 return true
end


if X.trainingQueueRunning then X.grade=false X.trait=false X.noRollLimit=X.trainingQueuePreviousNoLimit X.trainingQueueRunning=false end
S.reservedUnits={}
S.trainingQueueProtected={} for _,entry in X.trainingQueue do S.trainingQueueProtected[entry.id]=true end
do
 local session=G.BlueFarmTrainingBaseSession
 if session and session.job==game.JobId and session.user==P.UserId and session.part and session.part:IsDescendantOf(workspace) then
  local unit=D.GetData().PlayerUnits[session.id]
  if unit and not unit.Equipped then S.trainingBaseUnit=session.id S.trainingBaseSlot=session.part S.trainingBaseArmed=session.armed S.reservedUnits[session.id]=true end
 end
end
S.towerProtected={}
S.towerActiveUnits={}
S.inventoryQueue={} S.inventoryTicket=0
S.acquireInventory=function(owner)
 if S.inventoryOwner==owner then return true end
 local now=os.clock() local entry=S.inventoryQueue[owner]
 if not entry then S.inventoryTicket+=1 entry={ticket=S.inventoryTicket} S.inventoryQueue[owner]=entry end
 entry.at=now
 if S.inventoryBusy then return false end
 local first,number
 for name,row in S.inventoryQueue do
  if now-row.at>4 then S.inventoryQueue[name]=nil
  elseif not number or row.ticket<number then first=name number=row.ticket end
 end
 if first~=owner then return false end
 S.inventoryQueue[owner]=nil S.inventoryOwner=owner S.inventoryBusy=true S.inventorySince=now
 return true
end
S.releaseInventory=function(owner)
 if S.inventoryOwner~=owner then return false end
 S.inventoryOwner=nil S.inventoryBusy=false S.inventorySince=nil
 return true
end
do (function()
 local module=RS.Shared.Services:FindFirstChild("DayNightService")
 local day=module and require(module)
 S.halloweenHasPriority=function()
  if not S.halloweenSceneActive and S.variantTokenHasPriority and S.variantTokenHasPriority() then return false end
  if S.halloweenTravel or S.halloweenSceneActive then return true end
  if S.nativeMenuRequested then return false end
  if not X.halloween or not X.halloweenPriority then return false end
  if X.halloweenHouses and day and day.CanTrickOrTreat() then return true end
  return X.halloweenCorn and S.halloween and S.halloween.cornTravelReady==true or false
 end
 S.characterTaskBusy=function()
  return S.graveTravel or S.graveSceneActive or S.halloweenTravel or S.halloweenSceneActive or S.trainingTravel or S.obbyTravel or S.sharedTravelActive or S.tpReturnActive or S.shopOpen
 end
end)() end
for _,id in X.towerTeam do S.towerProtected[id]=true end
if X.unit and D.GetData().PlayerUnits[X.unit] then S.reservedUnits[X.unit]=true else X.unit=nil end
