table.insert(localeRows,{"Confirming Candy Bag sale before Candy Corn","กำลังยืนยันการขายถุงขนมก่อนเก็บแคนดี้คอร์น","Confirming Candy Bag sale before Candy Corn"})
local localeExact={} for _,r in localeRows do localeExact[r[1]]=r end
local localized=setmetatable({},{__mode="k"})
local translate=(function()
local translationCache={th={},en={}} local translationCacheCount=0
return function(source)
 local cache=translationCache[language]
 if cache[source] then return cache[source] end
 local index=language=="en" and 3 or 2
 local exact=localeExact[source] if exact then return exact[index] or source end
 -- Match only the original string, never translated output (avoids cascading substitutions).
 local out={} local cursor=1
 while cursor<=#source do
 local first,last,row
 for _,r in localeRows do
 if r[index] then
 local a,b=string.find(source,r[1],cursor,true)
 if a and (r[1]=="ON" or r[1]=="OFF") and (string.sub(source,a-1,a-1):match("[%w_]") or string.sub(source,b+1,b+1):match("[%w_]")) then a=nil end
 if a and (not first or a<first or (a==first and b>last)) then first,last,row=a,b,r end
 end
 end
 if not first then table.insert(out,string.sub(source,cursor)) break end
 table.insert(out,string.sub(source,cursor,first-1)) table.insert(out,row[index]) cursor=last+1
 end
 local result=table.concat(out)
 if translationCacheCount>2048 then translationCache={th={},en={}} translationCacheCount=0 cache=translationCache[language] end
 cache[source]=result translationCacheCount+=1 return result
end
end)()
local function bindLanguage(o)
 if not (o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox")) then return end
 local property=o:IsA("TextBox") and "PlaceholderText" or "Text"
 local entry={source=o[property],rendered=nil,property=property} localized[o]=entry
 local function render()
 entry.rendered=translate(entry.source)
 if o[property]~=entry.rendered then o[property]=entry.rendered end
 end
 local connection=o:GetPropertyChangedSignal(property):Connect(function()
 if o[property]~=entry.rendered then entry.source=o[property] render() end
 end)
 table.insert(connections,connection)
 render()
end
local languageRefresh
local function setLanguage(value)
 if value~="th" and value~="en" then return end
 language=value G.BlueFarmLanguage=value S.language=value
 for o,e in localized do if o.Parent then e.rendered=translate(e.source) o[e.property or "Text"]=e.rendered end end
 if languageRefresh then languageRefresh() end
end
S.language=language
S.setLanguage=setLanguage

local pageColumns={}
S.uiPageEntries={}
local themeTargets=setmetatable({},{__mode="k"})
local function make(class,parent,props)
 local requestedParent=parent
 local columns=pageColumns[parent]
 if columns and (class=="TextLabel" or class=="TextButton" or class=="Frame") then
 local index=columns.count==1 and 1 or (columns.heights[1]<=columns.heights[2] and 1 or 2)
 columns.heights[index]+=(props.Size and props.Size.Y.Offset or 30)+8
 parent=columns[index]
 end
 local o=Instance.new(class) for k,v in props do
 o[k]=v
 if typeof(v)=="Color3" and (v==blue or v==Color3.fromRGB(0,171,190)) then
 themeTargets[o]=themeTargets[o] or {} themeTargets[o][k]=true
 end
 end if o:IsA("UIStroke") and S.currentBorderColor then o.Color=S.currentBorderColor end
 o.Parent=parent bindLanguage(o) if S.uiPageEntries[requestedParent] then table.insert(S.uiPageEntries[requestedParent],o) end return o
end
local function round(o,r)
 make("UICorner",o,{CornerRadius=UDim.new(0,r or 8)})
 if o:IsA("TextButton") then
 -- Neutral shading multiplies the chosen theme instead of replacing its hue.
 make("UIGradient",o,{Name="DepthShading",Rotation=90,Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.new(1,1,1)),ColorSequenceKeypoint.new(0.48,Color3.fromRGB(242,244,247)),ColorSequenceKeypoint.new(1,Color3.fromRGB(207,212,222))})})
 local edge=make("UIStroke",o,{Name="SurfaceEdge",ApplyStrokeMode=Enum.ApplyStrokeMode.Border,Color=Color3.new(1,1,1),Thickness=1,Transparency=0.88})
 table.insert(connections,o.MouseEnter:Connect(function()if edge.Parent then edge.Transparency=0.62 end end))
 table.insert(connections,o.MouseLeave:Connect(function()if edge.Parent then edge.Transparency=0.88 end end))
 elseif o:IsA("TextBox") then
 make("UIStroke",o,{Name="InsetEdge",Color=Color3.new(0,0,0),Thickness=1,Transparency=0.40})
 make("UIGradient",o,{Rotation=90,Color=ColorSequence.new(Color3.fromRGB(215,218,225),Color3.new(1,1,1))})
 end
end
local function label(parent,text,height)
 return make("TextLabel",parent,{Size=UDim2.new(1,-12,0,height or 28),BackgroundTransparency=1,Text=text,TextColor3=Color3.fromRGB(209,222,238),Font=Enum.Font.Gotham,TextSize=13,TextWrapped=true,TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Center})
end
do (function()
 S.uiTweens={}
 S.createFyrelithIcon=function(parent,size)
  local orb=make("Frame",parent,{Name="FyrelithIcon",Size=UDim2.fromOffset(size,size),BackgroundColor3=Color3.fromRGB(4,5,10),BorderSizePixel=0})
  make("UICorner",orb,{CornerRadius=UDim.new(1,0)})
  make("UIGradient",orb,{Name="IconDepth",Rotation=45,Color=ColorSequence.new(Color3.fromRGB(80,85,105),Color3.fromRGB(5,6,12))})
  for i=3,1,-1 do
   local glow=make("Frame",orb,{Name="NeonHalo"..i,AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0.5,0.5),Size=UDim2.new(1,i*2,1,i*2),BackgroundTransparency=1,BorderSizePixel=0})
   make("UICorner",glow,{CornerRadius=UDim.new(1,0)})
   make("UIStroke",glow,{Name="ThemeBorder",Color=blue,Thickness=i==1 and 1.5 or 2,Transparency=i==1 and 0.08 or 0.85+i*0.025})
  end
  -- The exact uploaded PNG is displayed with Fit. No crop, recolor, pixel edit,
  -- or re-encoding is applied; the surrounding frame supplies the neon depth.
  if S.fyrelithIconAsset then
   make("ImageLabel",orb,{Name="OriginalArtwork",AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0.5,0.5),Size=UDim2.fromScale(0.70,0.70),BackgroundTransparency=1,Image=S.fyrelithIconAsset,ImageColor3=Color3.new(1,1,1),ScaleType=Enum.ScaleType.Fit,Active=false,ZIndex=3})
  else
   make("TextLabel",orb,{Name="AssetUnavailable",Size=UDim2.fromScale(1,1),BackgroundTransparency=1,Text="F",TextColor3=Color3.new(1,1,1),TextSize=math.floor(size*0.45),Font=Enum.Font.BuilderSansBold})
  end
  return orb
 end
