local pages={} local tabs={} local pageRefresh={}
local menuFade=make("Frame",panel,{Name="MenuFade",Position=UDim2.fromOffset(202,114),Size=UDim2.new(1,-220,1,-165),BackgroundColor3=Color3.fromRGB(15,17,31),BackgroundTransparency=1,BorderSizePixel=0,ZIndex=50,Visible=false,Active=true})
local menuTransition=0 local menuTween
local function switchPage(name)
 if not pages[name] then return end
 header.Text="Fyrelith  /  "..(S.uiPageNames and S.uiPageNames[name] or name)
 if pages[name].Visible and not menuFade.Visible then return end
 menuTransition+=1 local token=menuTransition
 if menuTween then menuTween:Cancel() end
 if S.menuPageTween then S.menuPageTween:Cancel() end
 menuFade.Visible=true
 task.spawn(function()
 local tweenService=game:GetService("TweenService")
 local fadeOut=tweenService:Create(menuFade,TweenInfo.new(0.10,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{BackgroundTransparency=0})
 menuTween=fadeOut fadeOut:Play() fadeOut.Completed:Wait()
 if token~=menuTransition or not gui.Parent then return end
 for n,p in pages do p.Visible=n==name p.Position=UDim2.fromOffset(202,114) end
 local incoming=pages[name] incoming.Position=UDim2.fromOffset(190,114)
 S.menuPageTween=tweenService:Create(incoming,TweenInfo.new(0.22,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{Position=UDim2.fromOffset(202,114)}) S.menuPageTween:Play()
 if S.refreshNavigationTheme then S.refreshNavigationTheme() end
 local fadeIn=tweenService:Create(menuFade,TweenInfo.new(0.18,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{BackgroundTransparency=1})
 menuTween=fadeIn fadeIn:Play() fadeIn.Completed:Wait()
 if token~=menuTransition or not gui.Parent then return end
 menuFade.Visible=false menuTween=nil
 end)
end
