local function refreshNavigationTheme()
 local dark=Color3.fromRGB(10,10,20)
 sidebar.BackgroundColor3=Color3.new(1,1,1)
 sidebarGradient.Color=ColorSequence.new(Color3.fromRGB(32,35,48),Color3.fromRGB(17,20,29))
 for name,tab in tabs do
 local selected=pages[name].Visible
 local background=selected and Color3.fromRGB(56,60,76) or Color3.fromRGB(26,29,40)
 tab.BackgroundColor3=background
 tab.BackgroundTransparency=selected and 0.05 or 0.42
 local marker=tab:FindFirstChild("ActiveMarker") if marker then marker.Visible=selected marker.BackgroundColor3=blue end
 local function linear(v)return v<=0.04045 and v/12.92 or ((v+0.055)/1.055)^2.4 end
 local l=0.2126*linear(background.R)+0.7152*linear(background.G)+0.0722*linear(background.B)
 tab.TextColor3=(l+0.05)/0.05>=1.05/(l+0.05) and Color3.fromRGB(12,15,20) or Color3.fromRGB(242,247,250)
 end
end
