local function page(name,title)
 local sc=make("ScrollingFrame",panel,{Name=name,Position=UDim2.fromOffset(202,114),Size=UDim2.new(1,-220,1,-165),BackgroundTransparency=1,BorderSizePixel=0,ScrollBarThickness=3,ScrollBarImageColor3=blue,CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,Visible=false})
 make("UIListLayout",sc,{Padding=UDim.new(0,10),FillDirection=Enum.FillDirection.Horizontal,VerticalAlignment=Enum.VerticalAlignment.Top,SortOrder=Enum.SortOrder.LayoutOrder})
 make("UIPadding",sc,{PaddingBottom=UDim.new(0,12),PaddingRight=UDim.new(0,8)})
 local count=(name=="Setting" or name=="Boosts" or name=="Overview" or name=="Training" or name=="Events" or name=="Travel") and 1 or 2
 local columns={heights={0,0},count=count}
 for i=1,count do
 local column=make("Frame",sc,{Name="Section"..i,LayoutOrder=i,Size=UDim2.new(1/count,-6,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundColor3=Color3.fromRGB(22,21,37),BackgroundTransparency=0.18,BorderSizePixel=0}) round(column,5)
 make("UIStroke",column,{Color=Color3.fromRGB(76,64,103),Thickness=1,Transparency=0.35})
 make("UIPadding",column,{PaddingLeft=UDim.new(0,9),PaddingTop=UDim.new(0,8),PaddingBottom=UDim.new(0,10)})
 make("UIListLayout",column,{Padding=UDim.new(0,8),SortOrder=Enum.SortOrder.LayoutOrder})
 local title=label(column,count==1 and name or ("Section 0"..i.."   /   "..name),28) title.TextColor3=Color3.fromRGB(148,151,158) title.TextSize=12
 columns[i]=column
 end
 pageColumns[sc]=columns S.uiPageEntries[sc]={}
 local b=make("TextButton",nav,{Name=name,Size=UDim2.new(1,0,0,44),Text=({Overview="Home",Farm="Farm & Team",Boosts="Boosts",Market="Inventory & Shop",Training="Grade & Trait",Tower="Tower",Events="Halloween & World",Travel="Travel",Setting="Settings"})[name] or title,Font=Enum.Font.GothamMedium,TextSize=12,TextColor3=Color3.fromRGB(180,198,220),BackgroundColor3=Color3.fromRGB(55,65,77),BorderSizePixel=0}) round(b)
 make("Frame",b,{Name="ActiveMarker",Size=UDim2.new(0,3,1,-18),Position=UDim2.fromOffset(0,9),BackgroundColor3=blue,BorderSizePixel=0})
 pages[name]=sc tabs[name]=b
 b.Activated:Connect(function()switchPage(name)end)
 return sc
end
