local function field(parent,key,title,min,max)
 local row=make("Frame",parent,{Size=UDim2.new(1,-6,0,44),BackgroundColor3=Color3.fromRGB(22,21,37),BackgroundTransparency=0.18,BorderSizePixel=0}) round(row)
 local t=label(row,title,40) t.Position=UDim2.fromOffset(12,0) t.Size=UDim2.new(1,-122,0,40)
 local box=make("TextBox",row,{Name=key,Position=UDim2.new(1,-106,0,6),Size=UDim2.fromOffset(94,32),Text=tostring(X[key]),ClearTextOnFocus=false,BackgroundColor3=Color3.fromRGB(65,67,73),TextColor3=Color3.fromRGB(240,242,245),Font=Enum.Font.Gotham,TextSize=13,BorderSizePixel=0}) round(box)
 box.FocusLost:Connect(function() local n=tonumber(box.Text) if n and n==n and n<math.huge then X[key]=math.clamp(n,min,max) end box.Text=tostring(X[key]) end)
 row.Size=UDim2.new(1,-2,0,65) t.Size=UDim2.new(1,-122,0,28) t.TextSize=13
 box.Position=UDim2.new(1,-106,0,7) box.Size=UDim2.fromOffset(94,30)
 local track=make("Frame",row,{Name="SliderTrack",Position=UDim2.fromOffset(12,47),Size=UDim2.new(1,-136,0,4),BackgroundColor3=Color3.fromRGB(12,14,26),BorderSizePixel=0,Active=true}) round(track,3)
 local fill=make("Frame",track,{Name="Fill",Size=UDim2.fromScale(0,1),BackgroundColor3=blue,BorderSizePixel=0}) round(fill,3)
 make("UIGradient",fill,{Color=ColorSequence.new(Color3.fromRGB(108,124,255),Color3.fromRGB(206,163,255))})
 local knob=make("TextButton",track,{Name="Knob",AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0,0.5),Size=UDim2.fromOffset(13,13),Text="",BackgroundColor3=Color3.fromRGB(227,218,255),BorderSizePixel=0}) round(knob,9)
 make("UIStroke",knob,{Color=blue,Thickness=2,Transparency=0.35})
 local pointer local scroll local wasScrolling
 local logarithmic=max-min>10000
 local function ratio(value)
  value=math.clamp(tonumber(value) or min,min,max)
  if logarithmic then return math.log(1+value-min)/math.log(1+max-min) end
  return (value-min)/(max-min)
 end
 local function draw()
  local fraction=ratio(X[key]) fill.Size=UDim2.fromScale(fraction,1) knob.Position=UDim2.fromScale(fraction,0.5)
 end
 local function update(input)
  local fraction=math.clamp((input.Position.X-track.AbsolutePosition.X)/math.max(1,track.AbsoluteSize.X),0,1)
  local value=logarithmic and (math.exp(fraction*math.log(1+max-min))-1+min) or (min+fraction*(max-min))
  if max-min>=20 then value=math.floor(value+0.5) else value=math.floor(value*100+0.5)/100 end
  X[key]=math.clamp(value,min,max) box.Text=tostring(X[key]) draw()
 end
 for _,control in {track,knob} do table.insert(connections,control.InputBegan:Connect(function(input)
  if pointer or input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
  pointer=input scroll=row:FindFirstAncestorWhichIsA("ScrollingFrame") if scroll then wasScrolling=scroll.ScrollingEnabled scroll.ScrollingEnabled=false end update(input)
 end)) end
 table.insert(connections,UIS.InputChanged:Connect(function(input)if pointer and (input==pointer or pointer.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseMovement) then update(input) end end))
 table.insert(connections,UIS.InputEnded:Connect(function(input)if pointer and input==pointer then pointer=nil if scroll then scroll.ScrollingEnabled=wasScrolling end end end))
 table.insert(pageRefresh,function()if not box:IsFocused() then box.Text=tostring(X[key]) end if not pointer then draw() end end) draw()
 return row
end
S.requestGameMenu=function(button,callback)
 if S.nativeMenuRequested or S.shopOpen or S.selectingTraining then return end
 S.nativeMenuRequested=true
 task.spawn(function()
  local original=button:GetAttribute("ActionLabel") or button.Text
  button.Text=original
  local opened=false local observers={}
  for _,entry in {{"BallSkinGui","MainFrame"},{"SelectGui","MainFrame"},{"InfinityTowerGui","FloorSelectionMainFrame"},{"InfinityTowerGui","UnitsSelectionMainFrame"},{"InfinityTowerGui","BattleMainFrame"},{"HalloweenShopGui","MainFrame"}} do
   local native=P.PlayerGui:FindFirstChild(entry[1]) local frame=native and native:FindFirstChild(entry[2])
   if frame then table.insert(observers,frame:GetPropertyChangedSignal("Visible"):Connect(function()if frame.Visible then opened=true end end)) end
  end
  local function finishObservation()for _,c in observers do c:Disconnect() end table.clear(observers) end
  if S.cancelSharedTravel then S.cancelSharedTravel() end
  if S.stopCollectionTravel then S.stopCollectionTravel() end
  if not S.running then finishObservation() S.nativeMenuRequested=false return end
  local ok,err=pcall(callback)
  local openedUntil=os.clock()+3
  repeat task.wait(0.05) until not S.running or opened or S.shopOpen or S.selectingTraining or os.clock()>=openedUntil
  finishObservation() S.nativeMenuRequested=false
  if button.Parent then button.Text=original end
  if not ok then S.lastError="Game menu: "..tostring(err) return end
  if not S.shopOpen and not S.selectingTraining then
   S.nativeMenuStatus=opened and "Menu closed normally" or "Menu did not open • Try again"
   return
  end
  S.nativeMenuStatus="Menu opened"
  local close=make("TextButton",gui,{Name="CloseGameMenu",AnchorPoint=Vector2.new(1,0),Position=UDim2.new(1,-18,0,12),Size=UDim2.fromOffset(180,40),Text="Back to Fyrelith  ×",Font=Enum.Font.BuilderSansBold,TextSize=14,TextColor3=Color3.new(1,1,1),BackgroundColor3=Color3.fromRGB(38,42,56),BorderSizePixel=0,ZIndex=100}) round(close,9)
  make("UIStroke",close,{Color=S.currentBorderColor or blue,Thickness=1.3})
  local overlay=Instance.new("ScreenGui") overlay.Name="FyrelithNativeMenuClose" overlay.ResetOnSpawn=false overlay.DisplayOrder=10000 overlay.Parent=P.PlayerGui close.Parent=overlay
  close.Activated:Connect(function()
   if S.closeNativeMenu then pcall(S.closeNativeMenu)
   elseif S.closeHalloweenShop then pcall(S.closeHalloweenShop)
   elseif S.selectingTraining then
    local picker=require(RS.Client.Core.Gui.SelectGuiClient)
    if type(picker.Close)=="function" then pcall(picker.Close) end
    local native=P.PlayerGui:FindFirstChild("SelectGui") local frame=native and native:FindFirstChild("MainFrame")
    if frame then frame.Visible=false end
   end
  end)
  while S.running and (S.shopOpen or S.selectingTraining) do task.wait(0.1) end
  overlay:Destroy()
 end)
end
local function action(parent,name,callback)
 local b=make("TextButton",parent,{Size=UDim2.new(1,-6,0,38),Text=name,TextSize=12,Font=Enum.Font.GothamMedium,TextColor3=Color3.fromRGB(245,255,255),BackgroundColor3=Color3.fromRGB(0,171,190),BorderSizePixel=0}) round(b)
 b:SetAttribute("ActionLabel",name)
 b.Activated:Connect(function()
  local key=b.Name
  if key=="OpenBallSkinShop" or key=="OpenTowerMenu" or key=="SelectStriker" or key=="SelectBaseStriker" or key=="QueuePickBase" or key=="QueuePickSpare" or key=="SelectDiggingStriker" or key:match("^TeamSlot%d+$") or name=="Open Halloween Shop" then S.requestGameMenu(b,callback) else callback() end
 end)
 return b
end

