S.applyUITheme=function(color)
 if S.currentBorderColor~=color or not S.themeApplied then
  S.themeApplied=true S.currentBorderColor=color
  panel.GroupColor3=Color3.new(1,1,1)
  for obj,properties in themeTargets do if obj.Parent then
   for property in properties do
    if property=="TextColor3" then obj[property]=Color3.fromRGB(240,244,252)
    elseif property=="BackgroundColor3" then obj[property]=Color3.fromRGB(58,64,81)
    elseif property=="Color" and obj:IsA("UIStroke") then obj[property]=color end
   end
  end end
  header.TextColor3=Color3.fromRGB(245,247,255) brand.TextColor3=header.TextColor3 credit.TextColor3=header.TextColor3 mini.TextColor3=header.TextColor3
  refreshNavigationTheme()
  if S.refreshThemeSurfaces then S.refreshThemeSurfaces(color) end
 end
end

