local function targetGrid(title,names,key,display)
 local heading=label(training,title,30) heading.Name=key.."Heading"
 local holder=make("Frame",training,{Name=key,Size=UDim2.new(1,-6,0,math.ceil(#names/3)*38),BackgroundTransparency=1})
 local buttons={}
 for i,name in names do
 local b=make("TextButton",holder,{Name=name,Size=UDim2.new(1/3,-5,0,34),Position=UDim2.new((i-1)%3/3,0,0,math.floor((i-1)/3)*38),Text=display(name),Font=Enum.Font.GothamMedium,TextSize=11,BackgroundColor3=Color3.fromRGB(17,28,42),TextColor3=blue,BorderSizePixel=0}) round(b,5)
 buttons[name]=b
 b.Activated:Connect(function() X[key][name]=not X[key][name] or nil end)
 end
 local function refresh() for name,b in buttons do S.styleSelection(b,X[key][name]) b.Text=display(name) end end
 table.insert(pageRefresh,refresh) refresh()
end
