do
 S.itemCatalog={} S.variantCatalog={}
 local libraries=RS.Shared.Core.Storage.Game
 for _,moduleName in {"CollectableObjectsLibrary","ItemRainLibrary"} do
  local module=libraries:FindFirstChild(moduleName)
  if module then
   local ok,library=pcall(require,module)
   if ok and type(library)=="table" then
    for _,definition in library do if type(definition)=="table" and type(definition.ItemName)=="string" then S.itemCatalog[definition.ItemName]=true end end
   end
  end
 end
 local variantModule=libraries:FindFirstChild("VariantTokensLibrary")
 if variantModule then
  local ok,library=pcall(require,variantModule)
  if ok then for name in library do if type(name)=="string" then S.variantCatalog[name]=true end end end
 end

 -- Variant rewards have one selector, even when they arrive via Item Rain.
 for name in S.variantCatalog do S.itemCatalog[name]=nil end

 -- Reusable, compact multi-select popup. Selection maps remain unchanged.
 (function()
  local state={key=nil,title="",catalog={},category="All",rows={}}
  local overlay=make("TextButton",panel,{Name="EventSelector",Size=UDim2.fromScale(1,1),Text="",AutoButtonColor=false,Visible=false,BackgroundColor3=Color3.new(0,0,0),BackgroundTransparency=0.35,BorderSizePixel=0,ZIndex=40}) round(overlay,8)
  local dialog=make("Frame",overlay,{Name="Dialog",AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0.5,0.5),Size=UDim2.new(1,-80,1,-60),BackgroundColor3=Color3.fromRGB(25,27,33),BorderSizePixel=0,ZIndex=41,Active=true}) round(dialog,14)
  make("UIStroke",dialog,{Color=Color3.fromRGB(75,80,94),Transparency=0.3})
  local title=label(dialog,"",32) title.Position=UDim2.fromOffset(20,13) title.Size=UDim2.new(1,-80,0,32) title.Font=Enum.Font.GothamBold title.TextSize=20 title.ZIndex=42
  local description=label(dialog,"Choose multiple items. Changes are saved automatically.",25) description.Position=UDim2.fromOffset(20,48) description.Size=UDim2.new(1,-40,0,25) description.TextSize=12 description.TextColor3=Color3.fromRGB(156,168,189) description.ZIndex=42
  local close=make("TextButton",dialog,{Name="Close",Position=UDim2.new(1,-48,0,16),Size=UDim2.fromOffset(30,30),Text="×",TextSize=25,BackgroundColor3=Color3.fromRGB(43,46,55),TextColor3=Color3.fromRGB(237,241,247),BorderSizePixel=0,ZIndex=43}) round(close,8)
  local search=make("TextBox",dialog,{Name="Search",Position=UDim2.fromOffset(20,84),Size=UDim2.new(1,-40,0,38),PlaceholderText="Search items…",Text="",ClearTextOnFocus=false,Font=Enum.Font.Gotham,TextSize=13,BackgroundColor3=Color3.fromRGB(34,37,45),TextColor3=Color3.fromRGB(237,241,247),PlaceholderColor3=Color3.fromRGB(142,153,171),BorderSizePixel=0,ZIndex=42}) round(search,8)
  make("UIPadding",search,{PaddingLeft=UDim.new(0,12),PaddingRight=UDim.new(0,12)})
  local categories={}
  for i,name in {"All","Tokens","Potions"} do
   local button=make("TextButton",dialog,{Name="Category_"..i,Position=UDim2.new((i-1)/3,20-(i-1)*40/3,0,134),Size=UDim2.new(1/3,-20,0,30),Text=name,Font=Enum.Font.GothamMedium,TextSize=12,BorderSizePixel=0,ZIndex=42}) round(button,8)
   themeTargets[button]=nil categories[name]=button
   table.insert(connections,button.Activated:Connect(function()state.category=name if state.render then state.render() end end))
  end
  local list=make("ScrollingFrame",dialog,{Name="Items",Position=UDim2.fromOffset(20,178),Size=UDim2.new(1,-40,1,-252),BackgroundTransparency=1,BorderSizePixel=0,ScrollBarThickness=3,CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,ZIndex=42})
  make("UIGridLayout",list,{CellSize=UDim2.new(0.5,-7,0,70),CellPadding=UDim2.fromOffset(10,10),SortOrder=Enum.SortOrder.LayoutOrder})
  make("UIPadding",list,{PaddingRight=UDim.new(0,3),PaddingBottom=UDim.new(0,8)})
  local empty=label(dialog,"No matching items",35) empty.Position=UDim2.fromOffset(20,195) empty.Size=UDim2.new(1,-40,0,35) empty.ZIndex=43 empty.Visible=false
  local countLabel=label(dialog,"",26) countLabel.Name="SelectionCount" countLabel.Position=UDim2.new(0,20,1,-65) countLabel.Size=UDim2.new(0.4,0,0,26) countLabel.TextSize=12 countLabel.ZIndex=42
  local function footerButton(name,x,width)
   local button=make("TextButton",dialog,{Name=name:gsub("%s",""),Position=UDim2.new(x,0,1,-55),Size=UDim2.new(width,-10,0,34),Text=name,Font=Enum.Font.GothamMedium,TextSize=12,BackgroundColor3=Color3.fromRGB(42,45,54),TextColor3=Color3.fromRGB(236,240,246),BorderSizePixel=0,ZIndex=43}) round(button,8) return button
  end
  countLabel.Position=UDim2.new(0,20,1,-56)
  local selectAll=footerButton("Select shown",0.39,0.21)
  local selectNone=footerButton("Clear shown",0.60,0.20)
  local done=footerButton("Done",0.80,0.18)
  local pretty={rain="Item Rain",variant="Variant Tokens",Grade="Grade Tokens",Trait="Trait Tokens",CashPotion="Cash Potion",LuckPotion="Luck Potion",GradeSpeedPotion="Grade Speed Potion",BluetoothPotion="Bluetooth Potion"}
  local function display(name)return pretty[name] or name:gsub("(%l)(%u)","%1 %2")end
  S.eventChoiceDisplay=display
  local function group(name)
   if name:find("Potion",1,true) then return "Potions" end
   if name=="Grade" or name=="Trait" then return "Tokens" end
   return "Tokens"
  end
  local function matches(name)
   return (state.category=="All" or group(name)==state.category) and display(name):lower():find(search.Text:lower(),1,true)~=nil
  end
  local function closePopup()overlay.Visible=false search:ReleaseFocus()end
  state.render=function()
   if not overlay.Visible or not state.key then return end
   local selected,total,shown=0,0,0
   for name in state.catalog do total+=1 if X[state.key][name]~=false then selected+=1 end end
   for _,row in state.rows do
    local visible=row.key==state.key and state.catalog[row.name]~=nil and matches(row.name)
    row.button.Visible=visible
    if visible then
     shown+=1
     local enabled=X[state.key][row.name]~=false
     local available=S.collect and S.collect.available and S.collect.available[row.name] or 0
     row.description.Text=state.key=="eventKinds" and "Event source" or ("Spawned: "..available)
     row.switch.Text=enabled and "ON" or "OFF"
     S.styleSelection(row.switch,enabled)
     row.stroke.Color=enabled and blue or Color3.fromRGB(62,67,79)
     row.stroke.Transparency=enabled and 0.35 or 0.65
     row.button.BackgroundColor3=enabled and Color3.fromRGB(32,35,43):Lerp(blue,0.09) or Color3.fromRGB(31,33,40)
    end
   end
   for name,button in categories do button.Visible=state.key=="collectItems" S.styleSelection(button,state.category==name) end
   local top=state.key=="collectItems" and 178 or 134
   list.Position=UDim2.fromOffset(20,top) list.Size=UDim2.new(1,-40,1,-top-74)
   empty.Position=UDim2.fromOffset(20,top+17)
   list.ScrollBarImageColor3=blue S.styleSelection(done,true)
   countLabel.Text=selected.." / "..total.." selected"
   empty.Visible=shown==0
  end
  S.openEventSelector=function(key,heading,catalog)
   if not X[key] then return end
   state.key=key state.title=heading state.catalog=catalog state.category="All"
   title.Text=heading search.Text="" list.CanvasPosition=Vector2.zero
   local names={} for name in catalog do table.insert(names,name) end table.sort(names)
   for i,name in names do
    local id=key..":"..name
    if not state.rows[id] then
     local button=make("TextButton",list,{Name="Choice_"..name,Text="",AutoButtonColor=false,BackgroundColor3=Color3.fromRGB(32,35,43),BorderSizePixel=0,LayoutOrder=i,ZIndex=43}) round(button,10)
     local stroke=make("UIStroke",button,{Thickness=1})
     local nameLabel=label(button,display(name),27) nameLabel.Position=UDim2.fromOffset(12,8) nameLabel.Size=UDim2.new(1,-78,0,27) nameLabel.Font=Enum.Font.GothamBold nameLabel.TextSize=13 nameLabel.ZIndex=44
     local info=label(button,"",21) info.Position=UDim2.fromOffset(12,37) info.Size=UDim2.new(1,-24,0,21) info.TextSize=11 info.TextColor3=Color3.fromRGB(149,165,188) info.ZIndex=44
     local status=make("TextLabel",button,{Position=UDim2.new(1,-56,0,13),Size=UDim2.fromOffset(44,23),Text="",Font=Enum.Font.GothamBold,TextSize=10,BorderSizePixel=0,ZIndex=44}) round(status,7) themeTargets[status]=nil
     state.rows[id]={key=key,name=name,button=button,stroke=stroke,description=info,switch=status}
     table.insert(connections,button.Activated:Connect(function()X[key][name]=not (X[key][name]~=false) state.render()end))
    end
   end
