    head.Activated:Connect(function()group.expanded=not group.expanded body.Visible=group.expanded arrow.Text=group.expanded and "−" or "+" end)
    arrow.Text=group.expanded and "−" or "+"
   end
  end
  for _,column in pageColumns[page] do if typeof(column)=="Instance" then column:Destroy() end end
  pageColumns[page]=nil
 end
 local search=make("TextBox",panel,{Name="FeatureSearch",Position=UDim2.fromOffset(430,66),Size=UDim2.new(1,-450,0,32),BackgroundColor3=Color3.fromRGB(23,23,40),BackgroundTransparency=0.2,Text="",PlaceholderText="Search features…",ClearTextOnFocus=false,TextSize=13,TextColor3=Color3.fromRGB(229,226,243),PlaceholderColor3=Color3.fromRGB(136,135,160),Font=Enum.Font.BuilderSans,BorderSizePixel=0}) round(search,8)
