-- Pointer release decides between a tap and a drag. Activated is deliberately
-- unused: Roblox can emit it after a drag ends over the same button.
do
 local pointer local beganAt local beganPosition local iconStart local dragged=false
 local function pointerPosition(input) return Vector2.new(input.Position.X,input.Position.Y) end
 local function moveIcon(input)
 if not pointer then return end
 local delta=pointerPosition(input)-beganPosition
 if delta.Magnitude>=6 then dragged=true end
 if not dragged then return end
 local view=workspace.CurrentCamera.ViewportSize
 local inset=game:GetService("GuiService"):GetGuiInset()
 local available=Vector2.new(view.X,view.Y-inset.Y)
 local x=iconStart.X.Scale*available.X+iconStart.X.Offset+delta.X
 local y=iconStart.Y.Scale*available.Y+iconStart.Y.Offset+delta.Y
 icon.Position=UDim2.fromOffset(math.clamp(x,0,math.max(0,available.X-icon.AbsoluteSize.X)),math.clamp(y,0,math.max(0,available.Y-icon.AbsoluteSize.Y)))
 end
 table.insert(connections,icon.InputBegan:Connect(function(input)
 if pointer or (input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch) then return end
 pointer=input beganAt=os.clock() beganPosition=pointerPosition(input) iconStart=icon.Position dragged=false
 end))
 table.insert(connections,UIS.InputChanged:Connect(function(input)
 if pointer and ((pointer.UserInputType==Enum.UserInputType.Touch and input==pointer) or (pointer.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseMovement)) then moveIcon(input) end
 end))
 table.insert(connections,UIS.InputEnded:Connect(function(input)
 if not pointer or (input~=pointer and not (pointer.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseButton1)) then return end
 moveIcon(input)
 local tapped=not dragged and os.clock()-beganAt<=0.6
 pointer=nil
 if tapped then setMinimized(not minimized) end
 end))
end
