do (function()
 local tweenService=game:GetService("TweenService")
 local token=0 local opacityTween local scaleTween local iconTween
 local iconScale=make("UIScale",icon,{Scale=1})
 S.cancelWindowMotion=function()
  token+=1
  if opacityTween then opacityTween:Cancel() opacityTween=nil end
  if scaleTween then scaleTween:Cancel() scaleTween=nil end
  if iconTween then iconTween:Cancel() iconTween=nil end
 end
 S.animateWindow=function(value,instant)
  S.cancelWindowMotion() local thisToken=token
  local targetScale=S.uiFitScale or scale.Scale
  iconScale.Scale=1
  if instant then panel.Visible=not value panel.GroupTransparency=value and 1 or 0 scale.Scale=targetScale return end
  panel.Visible=true
  if not value then panel.GroupTransparency=1 scale.Scale=targetScale*0.965 end
  local duration=value and 0.16 or 0.24
  opacityTween=tweenService:Create(panel,TweenInfo.new(duration,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{GroupTransparency=value and 1 or 0})
  scaleTween=tweenService:Create(scale,TweenInfo.new(duration,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{Scale=value and targetScale*0.965 or targetScale})
  iconTween=tweenService:Create(iconScale,TweenInfo.new(0.10,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{Scale=0.91})
  opacityTween:Play() scaleTween:Play() iconTween:Play()
  task.spawn(function()
   task.wait(0.10)
   if thisToken~=token or not gui.Parent then return end
   iconTween=tweenService:Create(iconScale,TweenInfo.new(0.16,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{Scale=1}) iconTween:Play()
  end)
  task.spawn(function()
   task.wait(duration)
   if thisToken~=token or not gui.Parent then return end
   panel.Visible=not value panel.GroupTransparency=value and 1 or 0 scale.Scale=targetScale
  end)
 end
 S.fitWindow=function()
  local view=workspace.CurrentCamera.ViewportSize
  S.uiFitScale=math.max(0.2,math.min(1,(view.X-24)/panel.Size.X.Offset,(view.Y-58)/panel.Size.Y.Offset))
  scale.Scale=S.uiFitScale
  if S.reflowResponsive then S.reflowResponsive() end
 end
 S.setWindowSize=function(width,height)
  S.cancelWindowMotion()
  panel.Size=UDim2.fromOffset(math.clamp(math.floor(width+0.5),680,1600),math.clamp(math.floor(height+0.5),460,1100))
  panel.GroupTransparency=minimized and 1 or 0 panel.Visible=not minimized
  S.fitWindow()
  local view=workspace.CurrentCamera.ViewportSize
  panel.Position=UDim2.fromOffset(math.clamp(panel.Position.X.Offset,0,math.max(0,view.X-panel.Size.X.Offset*S.uiFitScale)),math.clamp(panel.Position.Y.Offset,0,math.max(0,view.Y-panel.Size.Y.Offset*S.uiFitScale)))
  S.windowSize={width=panel.Size.X.Offset,height=panel.Size.Y.Offset}
 end
 local handle=make("TextButton",panel,{Name="ResizeHandle",AnchorPoint=Vector2.new(1,1),Position=UDim2.new(1,-5,1,-5),Size=UDim2.fromOffset(26,26),BackgroundTransparency=1,Text="◢",TextSize=18,TextColor3=blue,Font=Enum.Font.BuilderSans,ZIndex=70})
 local pointer local startPoint local startSize local startScale
 S.beginWindowResize=function(point)
  S.cancelWindowMotion() startPoint=point startSize=panel.Size startScale=scale.Scale S.windowResizing=true
 end
 S.updateWindowResize=function(point)
  if not S.windowResizing then return end
  local delta=(point-startPoint)/math.max(0.2,startScale)
  S.setWindowSize(startSize.X.Offset+delta.X,startSize.Y.Offset+delta.Y)
 end
 S.endWindowResize=function()pointer=nil S.windowResizing=false if S.saveConfig then S.saveConfig() end end
 table.insert(connections,handle.InputBegan:Connect(function(input)
  if pointer or input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
  pointer=input S.beginWindowResize(Vector2.new(input.Position.X,input.Position.Y))
 end))
 table.insert(connections,UIS.InputChanged:Connect(function(input)
  if pointer and (input==pointer or pointer.UserInputType==Enum.UserInputType.MouseButton1 and input.UserInputType==Enum.UserInputType.MouseMovement) then S.updateWindowResize(Vector2.new(input.Position.X,input.Position.Y)) end
 end))
 table.insert(connections,UIS.InputEnded:Connect(function(input)if pointer and input==pointer then S.endWindowResize() end end))
 table.insert(connections,gui.Destroying:Connect(S.cancelWindowMotion))
 if loadedUI and validNumber(loadedUI.width) and validNumber(loadedUI.height) then S.setWindowSize(loadedUI.width,loadedUI.height) else S.fitWindow() end
end)() end

