local dragging=false local dragStart local startPosition local dragTouch
table.insert(connections,header.InputBegan:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=true dragStart=input.Position startPosition=panel.Position dragTouch=input end end))
table.insert(connections,UIS.InputEnded:Connect(function(input) if input==dragTouch or input.UserInputType==Enum.UserInputType.MouseButton1 then dragging=false end end))
table.insert(connections,UIS.InputChanged:Connect(function(input) if dragging and (input.UserInputType==Enum.UserInputType.MouseMovement or input==dragTouch) then local delta=input.Position-dragStart local view=workspace.CurrentCamera.ViewportSize panel.Position=UDim2.fromOffset(math.clamp(startPosition.X.Offset+delta.X,0,math.max(0,view.X-panel.AbsoluteSize.X)),math.clamp(startPosition.Y.Offset+delta.Y,0,math.max(0,view.Y-panel.AbsoluteSize.Y))) end end))
table.insert(connections,UIS.InputBegan:Connect(function(input,processed)
 if UIS:GetFocusedTextBox() or input.UserInputType~=Enum.UserInputType.Keyboard then return end
 if bindingKey then
 if input.KeyCode~=Enum.KeyCode.Unknown and input.KeyCode~=Enum.KeyCode.Escape then X.uiKey=input.KeyCode.Name end
 bindingKey=false return
 end
 if not processed and input.KeyCode.Name==X.uiKey then setMinimized(not minimized) end
end))
gui.Destroying:Connect(function()
 if S.closeNativeMenu then pcall(S.closeNativeMenu) end
 if S.closeHalloweenShop then pcall(S.closeHalloweenShop) end
 S.running=false
 if S.restoreFPSTextures then S.restoreFPSTextures() end
 if S.stopCollectionTravel then pcall(S.stopCollectionTravel) end
 if S.saveConfig then pcall(S.saveConfig) end
 for _,c in connections do c:Disconnect() end
end)
do
 local originals=setmetatable({},{__mode="k"})
 local active=false
 S.fpsBoost={active=false,changed=0}
 local function simplify(object)
  if not active or not object:IsDescendantOf(workspace) or originals[object] then return end
  local values
  if object:IsA("Decal") or object:IsA("Texture") then values={Transparency=object.Transparency}
  elseif object:IsA("MeshPart") then values={TextureID=object.TextureID,Material=object.Material}
  elseif object:IsA("SpecialMesh") then values={TextureId=object.TextureId}
  elseif object:IsA("BasePart") then values={Material=object.Material} end
  if not values then return end
  originals[object]=values
  for property in values do
   pcall(function()object[property]=property=="Transparency" and 1 or property=="Material" and Enum.Material.SmoothPlastic or "" end)
  end
  S.fpsBoost.changed+=1
 end
 S.restoreFPSTextures=function()
  active=false S.fpsBoost.active=false
  for object,values in originals do
   for property,value in values do pcall(function()object[property]=value end) end
   originals[object]=nil
  end
  S.fpsBoost.changed=0
 end
 table.insert(connections,workspace.DescendantAdded:Connect(function(object)
  if active then task.defer(function()simplify(object)end) end
 end))
 task.spawn(function()
  while S.running do
   if X.boostFPS and not active then
    active=true S.fpsBoost.active=true
    for _,selector in {"BasePart","Decal","Texture","SpecialMesh"} do
     for index,object in workspace:QueryDescendants(selector) do
      if not S.running or not X.boostFPS then break end
      simplify(object)
      if index%150==0 then task.wait() end
     end
     if not S.running or not X.boostFPS then break end
    end
   elseif not X.boostFPS and active then S.restoreFPSTextures() end
   task.wait(0.2)
  end
  S.restoreFPSTextures()
 end)
end
-- Idle protection is installed before game data and UI initialization.
S.antiAFK=G.FyrelithAntiAFK
S.checkAntiAFK=function()local anti=G.FyrelithAntiAFK return anti and anti.Pulse() end

-- Debounced auto-save with stable fingerprints and a last-good backup.
do
local lastFingerprint local lastGoodRaw
local function copySettings()
 local options={}
 for key,kind in optionKinds do
 local value=X[key]
 if kind=="table" and type(value)=="table" then
 local map={}
 if key=="trainingQueue" then for _,entry in value do table.insert(map,{id=entry.id,grades=table.clone(entry.grades),traits=table.clone(entry.traits)}) end
 elseif key=="towerTeam" then for slot=1,require(RS.Shared.Constants).InfinityTowerUnitSlots do if type(value[slot])=="string" then map[tostring(slot)]=value[slot] end end
 else for k,v in value do if type(k)=="string" and type(v)=="boolean" then map[k]=v end end end
 options[key]=map
 elseif kind=="boolean" and type(value)=="boolean" or kind=="string" and type(value)=="string" or kind=="number" and validNumber(value) then options[key]=value end
 end
 local conveyor={}
 for _,key in {"autoBuy","spawnBestLocker","warnings","variantFilter","autoSellLockers"} do conveyor[key]=config[key] end
 conveyor.variants=table.clone(config.variants) conveyor.boxes=table.clone(config.boxes)
 return {schema=1,placeId=game.PlaceId,userId=P.UserId,deviceId=S.device.id,enabled=S.enabled,language=G.BlueFarmLanguage or "th",options=options,conveyor=conveyor,ui={x=panel.Position.X.Offset,y=panel.Position.Y.Offset,minimized=minimized,width=panel.Size.X.Offset,height=panel.Size.Y.Offset}}
end
local function canonical(value)
 if type(value)~="table" then return http:JSONEncode(value) end
 local keys={} for key in value do table.insert(keys,key) end table.sort(keys,function(a,b)return tostring(a)<tostring(b)end)
 local rows={} for _,key in keys do table.insert(rows,http:JSONEncode(tostring(key))..":"..canonical(value[key])) end
 return "{"..table.concat(rows,",").."}"
end
S.saveConfig=function()
 if G.BlueFarm~=S then return false end
 local ok,result=pcall(function()
 local snapshot=copySettings()
 local fingerprint=canonical(snapshot)
 if fingerprint==lastFingerprint then return true end
 G.BlueFarmConfigSessions[configPath]=snapshot
 if type(writefile)~="function" then
 lastFingerprint=fingerprint configState.status="Config: session only" return true
 end
 local raw=http:JSONEncode(snapshot)
 -- Retain the previous valid content before updating the primary file.
 if not lastGoodRaw and type(readfile)=="function" then
 local readOK,previous=pcall(readfile,configPath)
 if readOK and type(previous)=="string" and #previous<250000 then
 local parseOK,parsed=pcall(function()return http:JSONDecode(previous)end)
 if parseOK and validEnvelope(parsed) then lastGoodRaw=previous end
 end
 end
 if lastGoodRaw then pcall(writefile,configPath..".bak",lastGoodRaw) end
 writefile(configPath,raw)
 lastGoodRaw=raw lastFingerprint=fingerprint configState.saves+=1 configState.lastError="" configState.status="Config: saved"
 return true
 end)
 if not ok then configState.lastError=tostring(result) configState.status="Config: save failed" return false end
 return result
end
table.insert(connections,gui.Destroying:Connect(function()S.saveConfig()end))
S.resetConfig=function()
 if G.BlueFarm~=S or not S.running then return false end
 S.enabled=false
 if S.stopCollectionTravel then pcall(S.stopCollectionTravel) end
 for key in X do X[key]=nil end
 for key,value in S.defaultSettings.options do X[key]=type(value)=="table" and table.clone(value) or value end
 for key in config do config[key]=nil end
 for key,value in S.defaultSettings.conveyor do config[key]=type(value)=="table" and table.clone(value) or value end
 X.fastTweenConfigured=true X.iconVisibilityConfigured=true
 for key in S.potionConsent do S.potionConsent[key]=false X[key]=false end
 table.clear(S.reservedUnits) table.clear(S.towerProtected)
 if S.restoreFPSTextures then S.restoreFPSTextures() end
 if S.trainingStops then table.clear(S.trainingStops) end
 bindingKey=false
 setLanguage("en")
 S.applyUITheme(Color3.fromRGB(X.themeR,X.themeG,X.themeB))
 panel.Position=S.defaultPanelPosition
 setMinimized(false)
 for _,refresh in pageRefresh do refresh() end
 if S.refreshSelectedUnit then S.refreshSelectedUnit() end
 S.enabled=true
 if S.refreshMasterStatus then S.refreshMasterStatus() end
 lastFingerprint=nil
 local saved=S.saveConfig()
 -- Reset both copies so the backup cannot restore old preferences.
 if saved and lastGoodRaw and type(writefile)=="function" then pcall(writefile,configPath..".bak",lastGoodRaw) end
 return saved
end
S.saveConfig()
task.spawn(function()
 while S.running and gui.Parent do task.wait(S.mobileLite and 3 or 0.75) if S.running and gui.Parent then S.saveConfig() end end
end)
end


local function safe(f,scope)
 local ok,err=pcall(f) if not ok then
 if scope=="Base" and S.restoreDisplacedLocker then pcall(S.restoreDisplacedLocker) end
 S.errors+=1 S.lastError=tostring(err)
 end
end
-- Compare every striker at level 1, keeping variant, grade and trait bonuses.
local function unitBase(unit)
 return U.GetPlayerUnitCashPerDrop(P,{PlayerUnitName=unit.PlayerUnitName,PlayerUnitVariant=unit.Variant,PlayerUnitLevel=1,PlayerUnitGrade=unit.Grade,PlayerUnitTrait=unit.Trait,PlayerUnitBallSkin=unit.BallSkin})
end
local function partBase(part)
 local a=part:GetAttributes()
 return U.GetPlayerUnitCashPerDrop(P,{PlayerUnitName=a.PlayerUnitName,PlayerUnitVariant=a.PlayerUnitVariant,PlayerUnitLevel=1,PlayerUnitGrade=a.PlayerUnitGrade,PlayerUnitTrait=a.PlayerUnitTrait,PlayerUnitBallSkin=a.PlayerUnitBallSkin})
end
local objectCache={}
local failedPlacement={}
local function canPlace(id) return id~=X.graveUnit and not S.reservedUnits[id] and not S.trainingQueueProtected[id] and G.BlueFarmSpareSale.pending~=id and os.clock()>=(failedPlacement[id] or 0) end
S.autoEquipScore=function(unit)
 return U.GetPlayerUnitCashPerDrop(P,{PlayerUnitName=unit.PlayerUnitName,PlayerUnitVariant=unit.Variant,PlayerUnitLevel=unit.Level or 1,PlayerUnitGrade=unit.Grade,PlayerUnitTrait=unit.Trait,PlayerUnitBallSkin=unit.BallSkin})
end
S.autoEquipBetter=function(a,al,b,bl)
 local tolerance=math.max(1,math.abs(a),math.abs(b))*1e-7
 return a>b+tolerance
end
S.bestAutoEquipSpare=function()
 local best
 for id,unit in D.GetData().PlayerUnits do
 if not unit.Equipped and canPlace(id) then
 local score=S.autoEquipScore(unit) local level=unit.Level or 1
 if not best or S.autoEquipBetter(score,level,best.score,best.level) or (score==best.score and (level>best.level or (level==best.level and id<best.id))) then best={id=id,score=score,level=level} end
 end
 end
 return best
end
S.autoEquipOccupant=function(part)
 local a=part:GetAttributes() local chosen
 for id,unit in D.GetData().PlayerUnits do
 if unit.Equipped and unit.PlayerUnitName==a.PlayerUnitName and (unit.Variant or "Normal")== (a.PlayerUnitVariant or "Normal") and (unit.Level or 1)==(a.PlayerUnitLevel or 1) and unit.Grade==a.PlayerUnitGrade and unit.Trait==a.PlayerUnitTrait and unit.BallSkin==a.PlayerUnitBallSkin then
 -- Favorite prevents selling, but does not lock a unit into its base slot.
 if S.reservedUnits[id] or S.trainingQueueProtected[id] then return id,true end
 if not chosen or id<chosen then chosen=id end
 end
 end
 return chosen,false
end
S.canSellLocker=function(name,variant)
 if B.IsBoxFavorited(P,name,variant) then return false end
 local rows={}
 for boxName,variants in D.GetData().Inventory.Boxes do for var,entry in variants do
 if (entry.Amount or 0)>0 and BL[boxName] then
 local score=0
 for unitName in BL[boxName].PlayerUnits do score=math.max(score,U.GetPlayerUnitCashPerDrop(P,{PlayerUnitName=unitName,PlayerUnitVariant=var,PlayerUnitLevel=1})) end
 table.insert(rows,{name=boxName,variant=var,amount=entry.Amount,score=score})
 end end end
 table.sort(rows,function(a,b)if a.score~=b.score then return a.score>b.score end if a.name~=b.name then return a.name<b.name end return a.variant<b.variant end)
 local remaining=config.keepLockers
 for _,entry in rows do
 local keep=math.min(remaining,entry.amount) remaining-=keep
 if entry.name==name and entry.variant==variant then return entry.amount>keep end
 end
 return false
end
S.restoreDisplacedLocker=function()
 local displaced=S.lockerDisplaced
 if not displaced then return end
 local original=D.GetData().PlayerUnits[displaced.id]
 if S.running and displaced.part.Parent and not displaced.part:GetAttribute("Type") and original and not original.Equipped then R.PlacePlayerUnitOnDropper:FireServer(displaced.part,displaced.id) end
 S.lockerDisplaced=nil
end
local timers={}
local function due(key,interval)
 local now=os.clock()
 if now<(timers[key] or 0) then return false end
 timers[key]=now+interval
 return true
end
local function objects(keys,plot)
 local key=table.concat(keys,",")
 local cached=objectCache[key]
 if cached and cached.plot==plot and os.clock()-cached.at<2 then return cached.items end
 local isDropper=keys[2]=="_activeHandlerType"
 local searchKeys=isDropper and {"Part","IsClientOwnedPlot"} or keys
 local seen={}
 local out={} for _,v in filtergc("table",{Keys=searchKeys},false) do
 if typeof(v.Part)=="Instance" and v.Part:IsDescendantOf(plot) and (not isDropper or type(v._computeAction)=="function") and not seen[v.Part] then
 seen[v.Part]=true table.insert(out,v)
 end end
 objectCache[key]={plot=plot,at=os.clock(),items=out}
 return out
end
-- Conveyor requests do not depend on the proximity UI's active client object.
task.spawn(function()
 local pending local completedKey local attemptKey local attempts=0
 local nextPurchaseAt=0 local nextRollAt=0 local observedPart local observedRoll
 local ownsLock=false
 local function release()
 if ownsLock then S.releaseInventory("Conveyor") ownsLock=false end
 end
 local function amount(name,var)
 local boxes=D.GetData().Inventory.Boxes local entry=boxes[name] and boxes[name][var]
 return entry and entry.Amount or 0
 end
 local function check()
 if pending then
 if amount(pending.name,pending.variant)>pending.before then
 S.bought+=1 completedKey=pending.key
 S.lastLockerBought={name=pending.name,variant=pending.variant}
 S.buyStatus="Bought "..pending.variant.." "..pending.name
 pending=nil release()
 elseif os.clock()<pending.deadline then return
 else
 S.buyStatus="Purchase unconfirmed; retrying after cooldown"
 pending=nil release() nextPurchaseAt=os.clock()+1.5
 end
 end
 if not S.running or not S.enabled then return end
 
 if not config.autoBuy then S.buyStatus="Auto Buy is OFF" return end
 if config.autoSellLockers then
  local total=0
  for _,variants in D.GetData().Inventory.Boxes do for _,entry in variants do total+=entry.Amount or 0 end end
  if total>config.keepLockers+3 then S.lockerBackpressure=true end
  if total<=config.keepLockers+1 then S.lockerBackpressure=false end
  if S.lockerBackpressure then
   local sellable=false
   for name,variants in D.GetData().Inventory.Boxes do
    for variant in variants do if S.canSellLocker(name,variant) then sellable=true break end end
    if sellable then break end
   end
   if not sellable then S.lockerBackpressure=false end
  end
  if S.lockerSale.pending or S.lockerBackpressure then S.buyStatus="Clearing surplus lockers before buying more" return end
 else S.lockerBackpressure=false end
 local home=workspace.Map.PlotModels:FindFirstChild(P.Name)
 local systems=home and home:FindFirstChild("Systems") local station=systems and systems:FindFirstChild("RollStation")
 local part=station and station:FindFirstChild("ConveyorPart")
 if not part then S.buyStatus="Waiting for your conveyor" return end
 local id=part:GetAttribute("RollId")
 if part~=observedPart or id~=observedRoll then
 observedPart=part observedRoll=id nextRollAt=os.clock()+math.max(0.2,B.GetConveyorRollCooldown(P))
 end
 local name=part:GetAttribute("BoxName") local var=part:GetAttribute("Variant") or "Normal"
 local key=tostring(id)..":"..tostring(name)..":"..var
 local selected=name and BL[name] and config.boxes[name]~=false and (not config.variantFilter or config.variants[var]~=false)
 S.conveyorFilterHold=X.stopAtFilter and selected and completedKey~=key and {key=key,name=name,variant=var} or nil
 if not selected then S.buyStatus="Skipped by filters • Select allowed lockers / variants in Farm" end
 if attemptKey~=key then attemptKey=key attempts=0 nextPurchaseAt=0 end
 if not B.HasBoxInventorySpace(P,1) or not S.purchaseSpace() then S.buyStatus=S.inventoryBlockedMessage() return end
 if selected and completedKey~=key then
 local price=B.GetConveyorBoxPrice(name,var)
 if price<=(D.GetData().Currency.Cash or 0) then
 if S.baseBusy then S.buyStatus="Waiting for base operations" return end
 if attempts<3 then
 if os.clock()<nextPurchaseAt then return end
 if not S.acquireInventory("Conveyor") then S.buyStatus="Queued for inventory" return end
 attempts+=1 ownsLock=true
 pending={name=name,variant=var,key=key,before=amount(name,var),deadline=os.clock()+2.5}
 S.buyStatus="Buying "..var.." "..name
 R.PurchaseConveyorRoll:FireServer(name,var,price)
 return
 end
 else S.buyStatus="Waiting: cash for "..name end
 end
 if S.conveyorFilterHold then
  if attempts>=3 then S.buyStatus="Roll paused • Purchase unconfirmed: "..var.." "..name
  else S.buyStatus="Roll paused • Waiting to buy "..var.." "..name end
  return
 end
 if P:GetAttribute("TutorialConveyorLock") then S.buyStatus="Finish the conveyor tutorial first" return end
 local untilTime=part:GetAttribute("RollCooldownUntil") or 0
 if workspace:GetServerTimeNow()<untilTime or os.clock()<nextRollAt then return end
 local warning=require(RS.Client.Core.Gui.WarningNewBoxGuiClient)
 if warning.IsOpen() then warning.Close() end
 nextRollAt=os.clock()+math.max(1,B.GetConveyorRollCooldown(P))
 R.NewRequestConveyorRoll:FireServer()
 S.conveyorRollRequests=(S.conveyorRollRequests or 0)+1
 if not name then S.buyStatus="Spawning conveyor locker" end
 end
 S.checkConveyor=check
 while S.running and gui.Parent do
 local ok,err=pcall(check)
 if not ok then pending=nil release() S.errors+=1 S.lastError="Conveyor: "..tostring(err) nextPurchaseAt=os.clock()+3 end
 task.wait(0.1)
 end
 release()
end)


-- Discover every cash upgrade, including entries hidden from the general menu.
task.spawn(function()
 local retryAt={}
 local preferred={"PlayerUnitExpansion","Luck","ConveyorLuck","OpenTimeBoost","CrateCashBoost","WalkSpeed","CratePolisherUnlock","CratePolisher"}
 local names={} local seen={}
 for _,name in preferred do if UL[name] then table.insert(names,name) seen[name]=true end end
 for name,def in UL do if not seen[name] and type(def)=="table" and type(def.GetPrice)=="function" then table.insert(names,name) end end
 S.upgradeTypes=#names
 local cursor=0
 while S.running and gui.Parent do
 if S.enabled and X.upgrades then safe(function()
 for offset=1,#names do
 local index=(cursor+offset-1)%#names+1
 local name=names[index] local def=UL[name]
 local count=US.GetTimesPurchased(P,name)
 local eligible=not def.MaxPurchases or count<def.MaxPurchases
 if name=="CratePolisher" and US.GetTimesPurchased(P,"CratePolisherUnlock")<1 then eligible=false end
 if eligible and def.CanPurchase then
 local ok,allowed=pcall(def.CanPurchase,{Player=P})
 eligible=ok and allowed==true
 end
 if eligible and os.clock()>=(retryAt[name] or 0) then
 local price=def.GetPrice(count)
 if type(price)=="number" and price>=0 and price<math.huge and price<=(D.GetData().Currency.Cash or 0) then
 cursor=index
 R.PurchaseUpgrade:FireServer(name)
 local deadline=os.clock()+0.8
 repeat task.wait() until not S.running or US.GetTimesPurchased(P,name)>count or os.clock()>=deadline
 local after=US.GetTimesPurchased(P,name)
 if after>count then
 S.gameUpgrades+=after-count
 if name=="Luck" or name=="ConveyorLuck" then S.luckUpgrades+=after-count end
 S.lastUpgrade={name=name,level=after,price=price}
 objectCache={}
 else retryAt[name]=os.clock()+3 end
 break
 end end
 end
 end) end
 task.wait(0.15)
 end
end)
-- React to newly collected crates without waiting for a polling tick.
task.spawn(function()
 local pickupAt=0
 local sales={}
 S.ballSales={confirmed=0,retries=0,pending=0,polished=0}
 local busy=false
 local collectPart
 local collectConnection local nextCollectAt=0
 local function collect()
 if os.clock()<nextCollectAt then return end
 nextCollectAt=os.clock()+0.1
 if busy or not S.running or not S.enabled or not gui.Parent then return end
 busy=true
 safe(function()
 local plot=workspace.Map.PlotModels:FindFirstChild(P.Name)
 if not plot then return end
 local systems=plot:FindFirstChild("Systems")
 local conveyor=systems and systems:FindFirstChild("TycoonConveyor")
 local part=conveyor and conveyor:FindFirstChild("CollectPart")
 if not part or not part:IsA("BasePart") then S.ballCollectStatus="Waiting for conveyor collect point" return end
 S.ballCollectStatus="Collecting / selling balls"
 if collectPart~=part then
 if collectConnection then collectConnection:Disconnect() end
 collectPart=part
 collectConnection=part:GetAttributeChangedSignal("PendingBallCount"):Connect(function() task.defer(collect) end)
 table.insert(connections,collectConnection)
 end
 local now=os.clock()
 if not S.graveOwnsInventory and not S.polisherFinishedWaiting and require(RS.Shared.Services.InventoryService).HasInventorySpace(P,1) and (X.autoSellCrates or S.polisherWantsCrates and S.polisherWantsCrates()) and (part:GetAttribute("PendingBallCount") or 0)>0 and now-pickupAt>=0.4 then
 pickupAt=now R.PickupCrateBox:FireServer(part)
 end
 local crates=D.GetData().Crates
 for id in crates do
 if S.canSellCrate and S.canSellCrate(id) then
 local attempt=sales[id]
 if not attempt or now>=attempt.nextAt then
  if attempt then S.ballSales.retries+=1 end
  local tries=attempt and attempt.tries+1 or 1
  sales[id]={tries=tries,nextAt=now+math.min(1,0.2+math.max(0,tries-3)*0.15)}
  -- Only disappearance from replicated inventory confirms the sale.
  if S.running and S.enabled and D.GetData().Crates[id] and S.canSellCrate(id) then R.SellCrate:FireServer(id) end
 end
 end
 end
 S.ballSales.pending=0
 for id in sales do
 if not D.GetData().Crates[id] then
 sales[id]=nil S.sold+=1 S.ballSales.confirmed+=1
 if S.shinyCrates and S.shinyCrates[id] then S.ballSales.polished+=1 S.shinyCrates[id]=nil end
 else S.ballSales.pending+=1 end
 end
 S.ballCollectStatus=(X.autoSellCrates or X.polisher or X.autoSellPolishedCrates) and not require(RS.Shared.Services.InventoryService).HasInventorySpace(P,1) and ("Cannot pick up balls • "..S.inventoryBlockedMessage()) or not X.autoSellCrates and (S.polisherWantsCrates and S.polisherWantsCrates() and "Feeding Polisher • Normal sales OFF" or "Auto Sell Crate OFF • Waiting for enabled Polisher or manual crates") or S.ballSales.pending>0 and ("Verifying ball sales: "..S.ballSales.pending.." pending • "..S.ballSales.retries.." retries") or ("Ball sales confirmed: "..S.ballSales.confirmed)
 end)
 busy=false
 end
 table.insert(connections,D.Signals.CrateDataChanged:Connect(function() task.defer(collect) end))
 while S.running and gui.Parent do collect() task.wait(0.1) end
end)
task.spawn(function()
 while S.running and gui.Parent do
 if S.enabled and not S.selectingTraining and S.acquireInventory("Base") then
 S.baseBusy=true
 safe(function()
 local plot=workspace.Map.PlotModels:FindFirstChild(P.Name) if not plot then return end
 local d=D.GetData()

 local drops=objects({"Part","_activeHandlerType","IsClientOwnedPlot"},plot)
 -- The dedicated fast-open worker owns locker opening and its in-flight guard.
 local opening,unlocked=0,0
 for _,v in drops do
 if v.Part:GetAttribute("Unlocked") then unlocked+=1 end
 if v.Part:GetAttribute("Type")=="Box" then opening+=1 end
 end
 S.waitingBoxes=opening
 -- Keep the ten best unequipped strikers; never include base occupants in the quota.
 if X.sellSpareStrikers and os.clock()>=(S.merchantNext or 0) and due("sellSpareCheck",0.7) then
 local sale=G.BlueFarmSpareSale
 sale.attempts=sale.attempts or {}
 if sale.pending then
 if not D.GetData().PlayerUnits[sale.pending] then
 sale.sold+=1 sale.pending=nil sale.status="Sale confirmed"
 elseif os.clock()>=(sale.retryAt or 0) and (sale.attempts[sale.pending] or 0)<3 then
 -- Retry only an id still present after the confirmation window, never a sold id.
 sale.sent[sale.pending]=nil sale.pending=nil
 elseif os.clock()>=(sale.retryAt or 0) and (sale.attempts[sale.pending] or 0)>=3 then
 sale.failedId=sale.pending sale.pending=nil sale.status="Sale not confirmed after 3 attempts; skipped"
 else sale.status="Waiting for sale confirmation" end
 end
 local function rankSpares()
 local ranked={}
 for id,unit in D.GetData().PlayerUnits do
 if not unit.Equipped then table.insert(ranked,{id=id,unit=unit,base=S.autoEquipScore(unit)}) end
 end
