S.pickTowerSlot=function(slot)
 if X.towerBest then status.Tower="เลือกนักเตะเอง: ปิด Auto Equip Best ก่อน" return end
 if S.selectingTraining or (S.characterTaskBusy() or S.inventoryBusy) and not S.nativeMenuRequested then return end
 S.selectingTraining=true
 task.spawn(function()
 local oldVisible=panel.Visible local c
 local function restore()
 S.selectingTraining=false if panel.Parent then if S.setMinimized then S.setMinimized(false,true) else panel.Visible=true end end
 if c then c:Disconnect() c=nil end
 end
 local ok,err=pcall(function()
 if not alive() then restore() return end
 local excluded={}
 for i,id in X.towerTeam do if i~=slot then excluded[id]=true end end
 for id in S.reservedUnits do excluded[id]=true end
 for id in S.trainingQueueProtected do excluded[id]=true end
 if X.graveUnit~="" then excluded[X.graveUnit]=true end
 if G.BlueFarmSpareSale.pending then excluded[G.BlueFarmSpareSale.pending]=true end
 panel.Visible=false
 require(RS.Client.Core.Gui.SelectGuiClient).Open(function(id)
 if not alive() then return end
 if D.GetData().PlayerUnits[id] and not excluded[id] then
 X.towerTeam[slot]=id table.clear(S.towerProtected)
 for _,unitId in X.towerTeam do S.towerProtected[unitId]=true end
 end
 restore()
 end,nil,excluded,{IncludeEquipped=true})
 local frame=P.PlayerGui.SelectGui.MainFrame
 c=frame:GetPropertyChangedSignal("Visible"):Connect(function()if not frame.Visible then restore() end end)
 table.insert(connections,c)
 end)
 if not ok then status.Tower=tostring(err) restore() end
 end)
end
local towerManaged=false local towerActive=nil
worker("Tower",3,function()
 if X.towerLatest then X.towerName=latestTower() end
 if not X.tower then
 if towerManaged and towerActive then R.SetInfinityTowerAutoBattle:FireServer(towerActive,false) towerManaged=false end
 table.clear(S.towerActiveUnits) status.Tower="OFF" return
 end
 local current=R.GetInfinityTowerBattleState:InvokeServer()
 if not alive() or not S.enabled or not X.tower then return end
 if current then
 towerActive=current.TowerName
 if not current.AutoBattle then R.SetInfinityTowerAutoBattle:FireServer(current.TowerName,true) end
 towerManaged=true status.Tower=current.TowerName.." • ชั้น "..tostring(current.Floor).." • Auto Battle" return
 end
 local reason=IT.GetPlayBlockReason(P,X.towerName) if reason then status.Tower=reason return end
 if not ready("towerStart",12) then return end
 local team={}
 if X.towerBest then
 local battle=require(RS.Shared.Services.InfinityTowerBattleService)
 local units={} for id in D.GetData().PlayerUnits do if id~=X.graveUnit and not S.reservedUnits[id] then table.insert(units,{id=id,score=battle.GetDamageFromCashPerDrop(U.GetDamageBasis(P,id))*battle.GetHealthFromCashPerDrop(U.GetHealthBasis(P,id))}) end end
 table.sort(units,function(a,b)if a.score==b.score then return a.id<b.id end return a.score>b.score end)
 for i=1,math.min(#units,require(RS.Shared.Constants).InfinityTowerUnitSlots) do table.insert(team,units[i].id) end
 else
 local seen={}
 for i=1,require(RS.Shared.Constants).InfinityTowerUnitSlots do
 local id=X.towerTeam[i]
 if id and id~=X.graveUnit and D.GetData().PlayerUnits[id] and not seen[id] and not S.reservedUnits[id] then table.insert(team,id) seen[id]=true end
 end
 end
 if #team==0 then status.Tower="ยังไม่ได้เลือกทีมหอคอย" return end
 table.clear(S.towerActiveUnits) for _,id in team do S.towerActiveUnits[id]=true end
 local result=R.StartInfinityTowerBattle:InvokeServer(X.towerName,team)
 if type(result)=="table" and result.TowerName then
 towerActive=result.TowerName towerManaged=true
 if alive() and S.enabled and X.tower then R.SetInfinityTowerAutoBattle:FireServer(result.TowerName,true) end
 status.Tower=result.TowerName.." • เริ่มทีม "..#team.." ตัว" S.confirmed.towerStarts=(S.confirmed.towerStarts or 0)+1
 else table.clear(S.towerActiveUnits) status.Tower="เริ่มรอบยังไม่ยืนยัน" end
end)
-- Also disable server auto-battle when the master pause is used.
task.spawn(function() while alive() do if towerManaged and towerActive and (not S.enabled or not X.tower) then pcall(function()R.SetInfinityTowerAutoBattle:FireServer(towerActive,false)end) towerManaged=false end task.wait(0.25) end if towerManaged and towerActive then pcall(function()R.SetInfinityTowerAutoBattle:FireServer(towerActive,false)end) end end)
