-- One TP/Tween operation at a time; all cancellation paths release character state.
task.spawn(function()
 local tweenService=game:GetService("TweenService")
 while alive() do
 local ok,err=pcall(function()
 if S.travelSuspended then collect.status="Travel paused • Check Travel diagnostics" stopWalking() return end
 if S.tpReturnActive then return end
 if not S.enabled or S.nativeMenuRequested or S.graveHasPriority and S.graveHasPriority() or not (X.mapCollect or X.events or X.halloween or X.autoGrave) or S.selectingTraining or S.trainingTravel or S.tpReturnActive or S.sharedTravelActive or S.halloweenTravel or S.halloweenSceneActive or S.graveTravel or S.graveSceneActive or S.obbyTravel or S.shopOpen or S.halloweenHasPriority() then stopWalking() return end
 if manualControl() then collect.status="พักเดิน: กำลังควบคุมตัวละคร" stopWalking() return end
 local character=P.Character local root=character and character:FindFirstChild("HumanoidRootPart")
 local human=character and character:FindFirstChildOfClass("Humanoid")
 if not root or not human or human.Health<=0 or human.Sit or root.Anchored then stopWalking() return end
 local originPoint=safeStanding(root.Position,character,human,root)
 if not originPoint then collect.status="Waiting for solid ground" stopWalking() return end
 lastSafe={character=character,frame=CFrame.new(originPoint)*root.CFrame.Rotation}
 local target,nearest
 local variantFirst=S.variantTokenHasPriority()
 for _,c in candidates do
 if (not variantFirst or c.kind=="variant") and exists(c) and enabledTarget(c) and S.canTravelTarget(c) and os.clock()>=(routeBlocked[c.key] or 0) then
 local distance=(root.Position-c.pos).Magnitude
 if distance>S.travelValue("travelRange") and (not nearest or distance<nearest) then target=c nearest=distance end
 end
 end
 if not target then collect.status=#candidates>0 and "หาเส้นทางไม่ได้ • ข้ามชั่วคราว" or "ไม่พบของให้เก็บ" stopWalking() return end
 local mode=X.collectMode=="TP" and "TP" or "Tween"
 collect.walking=true collect.target=target.name collect.variantNode=target.kind=="variant" and target.node or nil collect.mode=mode walkingHumanoid=human
 collect.status="กำลังเก็บด้วย "..mode.." • "..target.name
 local function continuing()
 return alive() and S.enabled and X.collectMode==mode and not S.selectingTraining and not S.trainingTravel and not S.obbyTravel and not S.graveTravel and not S.graveSceneActive and not S.shopOpen and not S.nativeMenuRequested and not (S.graveHasPriority and S.graveHasPriority()) and not S.halloweenHasPriority() and not S.halloweenTravel and not S.halloweenSceneActive and (target.kind=="variant" or not S.variantTokenHasPriority()) and enabledTarget(target) and exists(target) and not manualControl() and P.Character==character and root.Parent~=nil and human.Health>0
 end
 local params=RaycastParams.new() params.FilterType=Enum.RaycastFilterType.Exclude
 local excluded={character} if target.node then table.insert(excluded,target.node) end
 params.FilterDescendantsInstances=excluded params.RespectCanCollide=true params.CollisionGroup=root.CollisionGroup
 local height=human.RigType==Enum.HumanoidRigType.R6 and 3 or math.max(2.5,human.HipHeight+root.Size.Y/2)
 local function standingPosition(pos)
 return safeStanding(pos,character,human,root,target.node)
 end
 local approach=target.pos
 local destinationPoint
 local offsets={Vector3.new(3,0,0),Vector3.new(-3,0,0),Vector3.new(0,0,3),Vector3.new(0,0,-3),Vector3.zero}
 local attempted=target.node and S.attemptedTargets[target.node] or S.attemptedRain[target.id]
 local shift=type(attempted)=="table" and attempted.count or 0
 for index=1,#offsets do
  local offset=offsets[(index+shift-1)%#offsets+1]
  local point=standingPosition(target.pos+offset)
  if point and (point-target.pos).Magnitude<=S.travelValue("travelRange") then destinationPoint=point break end
 end
 if not destinationPoint or (destinationPoint-target.pos).Magnitude>S.travelValue("travelRange") then
 routeBlocked[target.key]=os.clock()+S.travelValue("travelUnsafeRetry") collect.status="Unsafe item location; skipped" stopWalking() return
 end
 approach=destinationPoint
 if mode=="TP" then
 if not continuing() then stopWalking() return end
 if os.clock()<(S.nextTravelTP or 0) then stopWalking() return end
 local trip={key=target.key,ignore=target.node,origin=lastSafe.frame,root=root,character=character,human=human,item=target.name,before=ownedItem(target.name)}
 trip.wasAnchored=root.Anchored
 tpTrip=trip
 root.AssemblyLinearVelocity=Vector3.zero root.AssemblyAngularVelocity=Vector3.zero
 if not continuing() then tpTrip=nil stopWalking() return end
 -- One travel attempt per spawn. Only a new Occupied transition or rain id
 -- makes it eligible again; a timeout cannot repeatedly teleport to stale data.
 S.recordTravelAttempt(target)
 root.Anchored=true
 if not S.performTP(CFrame.new(approach)*root.CFrame.Rotation,continuing,"collection outward",target.node) then root.Anchored=trip.wasAnchored tpTrip=nil stopWalking() return end
 collect.teleports=(collect.teleports or 0)+1
 -- Let the character position replicate before the first pickup request.
 local requestAt=os.clock()+S.travelValue("travelSettle")
 local finish=requestAt+S.travelValue("pickupTimeout")
 repeat
 task.wait(0.02)
 -- Release after one replication frame so the server receives the new
 -- character position. The support watchdog remains active while waiting.
 if tpTrip==trip and root.Anchored then root.AssemblyLinearVelocity=Vector3.zero root.AssemblyAngularVelocity=Vector3.zero root.Anchored=trip.wasAnchored end
 if tpTrip==trip and ((root.Position-approach).Magnitude>6 or not safeStanding(root.Position,character,human,root,target.node)) then
 S.travelAudit.interruption={time=workspace:GetServerTimeNow(),deviation=(root.Position-approach).Magnitude,expected={approach.X,approach.Y,approach.Z},actual={root.Position.X,root.Position.Y,root.Position.Z},supported=safeStanding(root.Position,character,human,root,target.node)~=nil}
 collect.status="Unsafe position; returning immediately"
 routeBlocked[target.key]=os.clock()+S.travelValue("travelUnsafeRetry")
 returnFromTP(false)
 if S.travelSuspended and S.travelSuspendReason=="Unsupported or changed character position • Travel stopped" and (S.collectionRecoveries or 0)<3 and P.Character==character then
  task.wait(0.5)
  if alive() and S.enabled and not manualControl() and P.Character==character and human.Health>0 and safeStanding(root.Position,character,human,root) then
   S.collectionRecoveries=(S.collectionRecoveries or 0)+1 S.travelSuspended=false S.travelSuspendReason=nil
   collect.status="Returned safely • Skipping failed pickup route"
  end
 end
 end
 if tpTrip==trip and continuing() and os.clock()>=requestAt and (root.Position-target.pos).Magnitude<=S.travelValue("travelRange") then
 requestAt=os.clock()+S.travelValue("pickupRetry")
 collect.lastPickup={kind=target.kind,distance=(root.Position-target.pos).Magnitude,item=target.name}
 requestPickup(target.key,target.name,function()
 if target.kind=="map" then R.CollectCollectableObject:FireServer(target.node)
 elseif target.kind=="variant" then R.CollectVariantTokenSpawn:FireServer(target.node)
 else R.CollectItemRainItem:FireServer(target.id) end
 end)
 end
 if tpTrip==trip and ownedItem(trip.item)>trip.before then returnFromTP(true) end
 until tpTrip~=trip or not continuing() or os.clock()>=finish
 if tpTrip==trip and ownedItem(trip.item)<=trip.before then routeBlocked[target.key]=os.clock()+S.travelValue("travelUnsafeRetry") end
 if tpTrip==trip then returnFromTP(false) end
 stopWalking() return
 end
 local path=pathfinding:CreatePath({AgentRadius=1.5,AgentHeight=5,AgentCanJump=true,WaypointSpacing=12})
 local tweenItemBefore=ownedItem(target.name)
 path:ComputeAsync(root.Position,approach)
 if not continuing() then stopWalking() return end
 local waypoints
 if path.Status==Enum.PathStatus.Success then
 waypoints=path:GetWaypoints()
 elseif not workspace:Raycast(root.Position,Vector3.new(approach.X,root.Position.Y,approach.Z)-root.Position,params) then
 waypoints={{Position=approach}}
 else routeBlocked[target.key]=os.clock()+S.travelValue("travelUnsafeRetry") collect.status="หาเส้นทางไม่ได้ • ข้ามชั่วคราว" stopWalking() return end
 travelOrigin=lastSafe.frame
 S.recordTravelAttempt(target)
 anchoredRoot=root previousAnchored=root.Anchored root.Anchored=true
 S.collectionNoclipRelease=S.beginTravelNoclip(character)
 rotateHumanoid=human previousAutoRotate=human.AutoRotate human.AutoRotate=false
 root.AssemblyLinearVelocity=Vector3.zero root.AssemblyAngularVelocity=Vector3.zero
 local started=os.clock()
 for _,waypoint in waypoints do
 if not continuing() or (root.Position-approach).Magnitude<=0.4 then break end
 local destination=standingPosition(waypoint.Position+Vector3.new(0,height,0))
 if not destination then
  -- Navmesh stair/edge waypoints need not support a stationary character's
  -- full footprint. Stay anchored across them; only release at a safe endpoint.
  local hit=workspace:Raycast(waypoint.Position+Vector3.new(0,height+1,0),Vector3.new(0,-height-5,0),params)
  if hit and hit.Normal.Y>=0.5 and (not hit.Instance:IsA("BasePart") or hit.Instance.Anchored) then destination=hit.Position+Vector3.new(0,height+0.15,0) end
 end
 if not destination then collect.routeFailure={position=waypoint.Position,reason="No supported waypoint"} routeBlocked[target.key]=os.clock()+S.travelValue("travelUnsafeRetry") break end
 while continuing() and (root.Position-destination).Magnitude>0.3 do
 local speed=math.clamp(tonumber(X.collectTweenSpeed) or 600,5,2000)
 local duration=math.max(0.02,(root.Position-destination).Magnitude/speed)
 local tween=tweenService:Create(root,TweenInfo.new(duration,Enum.EasingStyle.Linear),{CFrame=CFrame.new(destination)*root.CFrame.Rotation})
 activeTravelTween=tween tween:Play()
 repeat task.wait(0.01) until not continuing() or tween.PlaybackState~=Enum.PlaybackState.Playing or X.collectTweenSpeed~=speed or (root.Position-approach).Magnitude<=0.4 or os.clock()-started>S.travelValue("travelTimeout")
 tween:Cancel() if activeTravelTween==tween then activeTravelTween=nil end
 if os.clock()-started>S.travelValue("travelTimeout") or X.collectTweenSpeed==speed then break end
 end
 if os.clock()-started>S.travelValue("travelTimeout") then routeBlocked[target.key]=os.clock()+S.travelValue("travelUnsafeRetry") break end
 end
 collect.tweenTrips=(collect.tweenTrips or 0)+1
 local tweenOrigin=travelOrigin
 -- Replicate the final position and explicitly collect, just as TP does.
 if continuing() and (root.Position-target.pos).Magnitude<=S.travelValue("travelRange") then
  if S.collectionNoclipRelease then S.collectionNoclipRelease() S.collectionNoclipRelease=nil end
  root.Anchored=previousAnchored
  local before=tweenItemBefore
  local requestAt=os.clock()+S.travelValue("travelSettle")
  local finish=requestAt+S.travelValue("pickupTimeout")
  repeat
   task.wait(0.02)
   if not continuing() or ownedItem(target.name)>before then break end
   if not standingPosition(root.Position) then safeReturn(travelOrigin,character,human,root) break end
   if os.clock()>=requestAt and (root.Position-target.pos).Magnitude<=S.travelValue("travelRange") then
    requestAt=os.clock()+S.travelValue("pickupRetry")
    collect.lastPickup={kind=target.kind,distance=(root.Position-target.pos).Magnitude,item=target.name,mode="Tween"}
    requestPickup(target.key,target.name,function()
     if target.kind=="map" then R.CollectCollectableObject:FireServer(target.node)
     elseif target.kind=="variant" then R.CollectVariantTokenSpawn:FireServer(target.node)
     else R.CollectItemRainItem:FireServer(target.id) end
    end)
   end
  until os.clock()>=finish
  if continuing() and ownedItem(target.name)<=before then routeBlocked[target.key]=os.clock()+S.travelValue("travelRetryDelay") end
 end
 if ownedItem(target.name)>tweenItemBefore then S.confirmCollectionReceipt(target.key) end
 stopWalking()
 if X.collectReturnTween and tweenOrigin and P.Character==character and root.Parent and human.Health>0 and S.travelTo then
  S.travelTo(tweenOrigin,function()return alive() and S.enabled and not manualControl() and P.Character==character end)
 end
 end)
 if not ok then stopWalking() collect.status=tostring(err) S.lastError="Collect movement: "..tostring(err) S.errors+=1 end
 task.wait(0.15)
 end
 stopWalking()
end)


