do local ok,err=xpcall(function() -- Modern shell
-- Live UI replacement; keeps the running controller and its existing callbacks.
local P=game:GetService('Players').LocalPlayer
local UIS=game:GetService('UserInputService')
local S=getgenv().BlueFarm
assert(S,'Start the original BlueFarm controller first')
local gui=P.PlayerGui:WaitForChild('BlueFarmControls')
local old=gui:WaitForChild('Dashboard')
local previous=gui:FindFirstChild('FyrelithModern')
if previous then previous:Destroy() end
local C={bg=Color3.fromRGB(12,13,16),card=Color3.fromRGB(23,24,29),text=Color3.fromRGB(238,240,241),muted=Color3.fromRGB(133,139,149),mint=Color3.fromRGB(199,237,224),purple=Color3.fromRGB(82,29,71)}
local function make(t,p,props)
 local v=Instance.new(t) for k,x in pairs(props or {}) do v[k]=x end v.Parent=p return v
end
local function round(v,n) make('UICorner',v,{CornerRadius=UDim.new(0,n or 12)}) end
local function label(p,txt,size,pos,box,color)
 return make('TextLabel',p,{BackgroundTransparency=1,Text=txt,TextSize=size,Font=Enum.Font.Gotham,TextColor3=color or C.text,TextXAlignment=Enum.TextXAlignment.Left,Position=pos,Size=box})
end
local shell=make('Frame',gui,{Name='FyrelithModern',Size=UDim2.fromOffset(1060,700),Position=UDim2.fromScale(.5,.5),AnchorPoint=Vector2.new(.5,.5),BackgroundColor3=C.bg,ClipsDescendants=true}) round(shell,24)
make('UIStroke',shell,{Color=Color3.fromRGB(49,47,56),Transparency=.25})
local scale=make('UIScale',shell,{Scale=1})
local function fit() local v=workspace.CurrentCamera.ViewportSize scale.Scale=math.min(1,(v.X-72)/1060,(v.Y-100)/700) end fit()
-- Viewport fitting is owned by responsive-fix below.
local rail=make('Frame',shell,{Name='Rail',Size=UDim2.new(0,76,1,0),BackgroundColor3=Color3.fromRGB(16,17,20),BorderSizePixel=0})
