do local ok,err=xpcall(function() -- resize
local u=getgenv().BlueFarm.modernUI
local shell=u.shell
local UIS=game:GetService('UserInputService')
local corner=shell:FindFirstChildOfClass('UICorner') or Instance.new('UICorner',shell)
corner.CornerRadius=UDim.new(0,26)
-- Round the opaque rail too so its square corners cannot cover the shell radius.
local rail=shell:FindFirstChild('Rail')
if rail then
 local c=rail:FindFirstChildOfClass('UICorner') or Instance.new('UICorner',rail)
 c.CornerRadius=UDim.new(0,24)
end
local existing=shell:FindFirstChild('CornerResize') if existing then existing:Destroy() end
if u.resizeConnections then for _,c in ipairs(u.resizeConnections) do c:Disconnect() end end
local grip=Instance.new('TextButton')
grip.Name='CornerResize' grip.Size=UDim2.fromOffset(38,38) grip.Position=UDim2.new(1,-43,1,-43)
grip.BackgroundTransparency=1 grip.Text='◢' grip.TextSize=23 grip.Font=Enum.Font.GothamBold
grip.TextColor3=Color3.fromRGB(199,237,224) grip.TextTransparency=.15 grip.ZIndex=50 grip.Parent=shell
local resizing=false
local startPoint,startScale,activeTouch
local scale=shell:FindFirstChildOfClass('UIScale')
local function maxScale()
 local v=workspace.CurrentCamera.ViewportSize
 return math.min(1.65,(v.X-40)/1060,(v.Y-70)/700)
end
local function apply(s)
 scale.Scale=math.clamp(s,math.min(.55,maxScale()),maxScale())
 u.userScale=scale.Scale
end
local connections={}
table.insert(connections,grip.InputBegan:Connect(function(i)
 if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then
  resizing=true startPoint=i.Position startScale=scale.Scale activeTouch=i.UserInputType==Enum.UserInputType.Touch and i or nil
  grip.TextColor3=Color3.new(1,1,1)
 end
end))
table.insert(connections,UIS.InputChanged:Connect(function(i)
 if not resizing then return end
 if i.UserInputType==Enum.UserInputType.MouseMovement or i==activeTouch then
  local d=i.Position-startPoint
  -- The window is centered on its anchor, so a scale change moves each edge by half.
  apply(startScale+2*(d.X*1060+d.Y*700)/(1060*1060+700*700))
 end
end))
table.insert(connections,UIS.InputEnded:Connect(function(i)
 if i.UserInputType==Enum.UserInputType.MouseButton1 or i==activeTouch then
  resizing=false activeTouch=nil grip.TextColor3=Color3.fromRGB(199,237,224)
 end
end))
table.insert(connections,workspace.CurrentCamera:GetPropertyChangedSignal('ViewportSize'):Connect(function() apply(u.userScale or scale.Scale) end))
u.resizeConnections=connections
u.resizeGrip=grip

end,debug.traceback) if not ok then getgenv().FyrelithFullError="resize: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- responsive-fix
local u=getgenv().BlueFarm.modernUI
local shell=u.shell
local UIS=game:GetService('UserInputService')
if u.resizeConnections then for _,c in ipairs(u.resizeConnections) do c:Disconnect() end end
local host=u.clipHost
if not host then
 host=Instance.new('CanvasGroup') host.Name='RoundedWindow' host.BackgroundTransparency=1 host.Size=UDim2.fromOffset(1060,700) host.Position=shell.Position host.AnchorPoint=shell.AnchorPoint host.ClipsDescendants=true host.Parent=shell.Parent
 local c=Instance.new('UICorner') c.CornerRadius=UDim.new(0,26) c.Parent=host
 local scale=shell:FindFirstChildOfClass('UIScale') if scale then scale.Parent=host end
 shell.Parent=host shell.Position=UDim2.fromOffset(0,0) shell.AnchorPoint=Vector2.zero shell.Size=UDim2.fromScale(1,1)
 u.clipHost=host
 shell:GetPropertyChangedSignal('Visible'):Connect(function() host.Visible=shell.Visible end)
end
local scale=host:FindFirstChildOfClass('UIScale')
local function fit()
 local vp=workspace.CurrentCamera.ViewportSize
 scale.Scale=math.max(0.01,math.min(1,(vp.X*0.86)/math.max(1,host.Size.X.Offset),(vp.Y*0.78)/math.max(1,host.Size.Y.Offset)))
end
local function reflow()
 local wide=host.Size.X.Offset>=900
 for _,page in pairs(u.pages) do
  local layout=page:FindFirstChildOfClass('UIListLayout')
  if layout then layout.FillDirection=wide and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical end
  for _,col in ipairs(page:GetChildren()) do
   if col:IsA('Frame') and col.Name:match('ResponsiveColumn') then
    col.Size=UDim2.new(wide and .5 or 1,wide and -6 or 0,0,0)
    col.AutomaticSize=Enum.AutomaticSize.Y
   end
  end
  page.AutomaticCanvasSize=Enum.AutomaticSize.Y
 end
 fit()
end
local grip=u.resizeGrip
local active=false local initial,initialSize,touch
local connections={}
table.insert(connections,grip.InputBegan:Connect(function(i)
 if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then
  active=true initial=i.Position initialSize=host.Size touch=i.UserInputType==Enum.UserInputType.Touch and i or nil
 end
end))
table.insert(connections,UIS.InputChanged:Connect(function(i)
 if active and (i.UserInputType==Enum.UserInputType.MouseMovement or i==touch) then
  local d=(i.Position-initial)/scale.Scale
  host.Size=UDim2.fromOffset(math.clamp(initialSize.X.Offset+d.X*2,680,1500),math.clamp(initialSize.Y.Offset+d.Y*2,600,1050))
  reflow()
 end
end))
table.insert(connections,UIS.InputEnded:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 or i==touch then active=false touch=nil end end))
table.insert(connections,workspace.CurrentCamera:GetPropertyChangedSignal('ViewportSize'):Connect(fit))
-- Existing header drag updates the inner shell; forward its movement to the host.
local moving=false
table.insert(connections,shell:GetPropertyChangedSignal('Position'):Connect(function()
 if moving or shell.Position==UDim2.fromOffset(0,0) then return end
 moving=true local p=shell.Position host.Position=UDim2.new(host.Position.X.Scale,host.Position.X.Offset+p.X.Offset,host.Position.Y.Scale,host.Position.Y.Offset+p.Y.Offset) shell.Position=UDim2.fromOffset(0,0) moving=false
end))
u.resizeConnections=connections
u.reflow=reflow
reflow()

end,debug.traceback) if not ok then getgenv().FyrelithFullError="responsive-fix: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- drag-fix
local u=getgenv().BlueFarm.modernUI
local UIS=game:GetService('UserInputService')
-- Replace the previous header gesture, which targeted the former outer frame.
for _,c in ipairs(getconnections(u.shell.Hero.InputBegan)) do c:Disconnect() end
local dragging=false local origin,start
u.shell.Hero.InputBegan:Connect(function(i)
 if i.UserInputType==Enum.UserInputType.MouseButton1 then dragging=true origin=u.clipHost.Position start=i.Position end
end)
UIS.InputChanged:Connect(function(i)
 if dragging and i.UserInputType==Enum.UserInputType.MouseMovement then
  local d=i.Position-start
  u.clipHost.Position=UDim2.new(origin.X.Scale,origin.X.Offset+d.X,origin.Y.Scale,origin.Y.Offset+d.Y)
 end
end)
UIS.InputEnded:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 then dragging=false end end)
u.clipHost.Size=UDim2.fromOffset(1060,700)
u.reflow()

end,debug.traceback) if not ok then getgenv().FyrelithFullError="drag-fix: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- input-fix
local u=getgenv().BlueFarm.modernUI
local UIS=game:GetService('UserInputService')
local gui=game.Players.LocalPlayer.PlayerGui.BlueFarmControls
if u.inputConnections then for _,c in ipairs(u.inputConnections) do c:Disconnect() end end
-- Remove the fixed RightShift shortcuts installed by the earlier UI versions.
for _,c in ipairs(getconnections(UIS.InputBegan)) do
 if c.Function then
  local ok,constants=pcall(debug.getconstants,c.Function)
  if ok then for _,v in ipairs(constants) do if v=='RightShift' then c:Disconnect() break end end end
 end
end
local bind=u.pages.Setting:FindFirstChild('BindUIKey',true)
assert(bind,'UI key button missing')
local keyName=bind.Text:match('UI Key:%s*(%w+)') or 'LeftControl'
u.hotkey=Enum.KeyCode[keyName] or Enum.KeyCode.LeftControl
local function visible(v)
 u.shell.Visible=v if u.clipHost then u.clipHost.Visible=v end
end
local function toggle() visible(not u.shell.Visible) end
u.toggleVisibility=toggle
local connections={}
local waiting=false
for _,signal in ipairs({bind.Activated,bind.MouseButton1Click}) do for _,c in ipairs(getconnections(signal)) do c:Disconnect() end end
table.insert(connections,bind.Activated:Connect(function() waiting=true bind.Text='Press a key... (Esc to cancel)' end))
table.insert(connections,UIS.InputBegan:Connect(function(i,processed)
 if waiting and i.UserInputType==Enum.UserInputType.Keyboard then
  waiting=false
  if i.KeyCode~=Enum.KeyCode.Escape and i.KeyCode~=Enum.KeyCode.Unknown then u.hotkey=i.KeyCode end
  bind.Text='UI Key: '..u.hotkey.Name
  getgenv().BlueFarmUIKey=u.hotkey.Name
  return
 end
 if not processed and not UIS:GetFocusedTextBox() and i.KeyCode==u.hotkey then toggle() end
end))
local hide=u.shell.Hero:FindFirstChild('Hide')
if hide then for _,c in ipairs(getconnections(hide.Activated)) do c:Disconnect() end table.insert(connections,hide.Activated:Connect(function() visible(false) end)) end
local icon=gui:FindFirstChild('ModernLauncher')
assert(icon,'Launcher missing')
for _,c in ipairs(getconnections(icon.Activated)) do c:Disconnect() end
local pressing=false local dragged=false local origin,start,touch local lastDrag=0
table.insert(connections,icon.InputBegan:Connect(function(i)
 if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then
  pressing=true dragged=false start=i.Position origin=icon.Position touch=i.UserInputType==Enum.UserInputType.Touch and i or nil
 end
end))
table.insert(connections,UIS.InputChanged:Connect(function(i)
 if pressing and (i.UserInputType==Enum.UserInputType.MouseMovement or i==touch) then
  local d=i.Position-start
  if d.Magnitude>5 then dragged=true end
  if dragged then
   local vp=workspace.CurrentCamera.ViewportSize
   icon.Position=UDim2.fromOffset(math.clamp(origin.X.Offset+d.X,0,vp.X-icon.AbsoluteSize.X),math.clamp(origin.Y.Offset+d.Y,0,vp.Y-icon.AbsoluteSize.Y))
   lastDrag=os.clock()
  end
 end
end))
table.insert(connections,UIS.InputEnded:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 or i==touch then pressing=false touch=nil end end))
table.insert(connections,icon.Activated:Connect(function() if not dragged and os.clock()-lastDrag>.2 then toggle() end end))
u.inputConnections=connections
u.inputReady=true

end,debug.traceback) if not ok then getgenv().FyrelithFullError="input-fix: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- modern-polish
local u=getgenv().BlueFarm.modernUI
local Tween=game:GetService('TweenService')
local mint=Color3.fromRGB(190,240,220)
local surface=Color3.fromRGB(26,31,40)
local border=Color3.fromRGB(66,78,91)
local function corner(v,r)
 local c=v:FindFirstChildOfClass('UICorner') or Instance.new('UICorner',v) c.CornerRadius=UDim.new(0,r)
end
local function edge(v)
 local e=v:FindFirstChildOfClass('UIStroke') or Instance.new('UIStroke',v)
 e.Color=border e.Transparency=.65 e.Thickness=1 return e
end
local function animate(v,props) Tween:Create(v,TweenInfo.new(.16,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),props):Play() end
if u.polishConnections then for _,c in ipairs(u.polishConnections) do c:Disconnect() end end
local connections={}
local names={'Overview','Farm','Boosts','Market','Training','Tower','Events','Travel','Setting'}
