local preview=new('ImageLabel',imageHost,{BackgroundTransparency=1,Size=UDim2.fromScale(1,1),ScaleType=Enum.ScaleType.Crop,Image='rbxthumb://type=GameThumbnail&id='..tostring(game.GameId)..'&w=768&h=432',ZIndex=4})
