do local ok,err=xpcall(function() -- depth-motion
if getgenv().BlueFarm.mobileLite then return end
local u=getgenv().BlueFarm.modernUI
local Tween=game:GetService('TweenService')
local mint=Color3.fromRGB(199,250,229)
if u.motionConnections then for _,c in ipairs(u.motionConnections) do c:Disconnect() end end
local connections={}
local activeTweens=setmetatable({},{__mode='k'})
local function animate(v,props,time)
 local old=activeTweens[v] if old then old:Cancel() end
 local t=Tween:Create(v,TweenInfo.new(time or .2,Enum.EasingStyle.Quint,Enum.EasingDirection.Out),props)
 activeTweens[v]=t t:Play()
end
local function edge(v,color,alpha)
 local s=v:FindFirstChildOfClass('UIStroke') or Instance.new('UIStroke',v)
 s.Color=color s.Transparency=alpha s.Thickness=1 return s
end
for _,b in ipairs(u.shell.Rail:GetChildren()) do
 if b:IsA('TextButton') then
  local icon=b:FindFirstChild('LineIcon')
  if icon then
   icon.Size=UDim2.fromOffset(27,27)
   local zoom=icon:FindFirstChildOfClass('UIScale') or Instance.new('UIScale',icon) zoom.Scale=1.05
   local function recolor()
    local selected=b.BackgroundColor3.G>.6
    for _,line in ipairs(icon:GetChildren()) do
     if line:IsA('Frame') then line.Size=UDim2.fromOffset(line.Size.X.Offset,2.7) line.BackgroundColor3=selected and Color3.fromRGB(17,44,37) or Color3.fromRGB(210,224,237) end
    end
   end
   recolor()
   table.insert(connections,b:GetPropertyChangedSignal('BackgroundColor3'):Connect(recolor))
   local e=edge(b,Color3.fromRGB(109,140,150),.8)
   table.insert(connections,b.MouseEnter:Connect(function() animate(zoom,{Scale=1.16}) animate(e,{Transparency=.35}) end))
   table.insert(connections,b.MouseLeave:Connect(function() animate(zoom,{Scale=1.05}) animate(e,{Transparency=.8}) end))
   table.insert(connections,b.MouseButton1Down:Connect(function() animate(zoom,{Scale=.95},.1) end))
   table.insert(connections,b.MouseButton1Up:Connect(function() animate(zoom,{Scale=1.16},.22) end))
  end
 end
end
for _,page in pairs(u.pages) do
 for _,v in ipairs(page:QueryDescendants('TextLabel, TextButton, TextBox, Frame')) do
  if v:IsA('TextLabel') then
   v.TextStrokeTransparency=1
   if v.Name=='Description' then
    v.Font=Enum.Font.Gotham v.TextSize=math.max(v.TextSize,11) v.TextColor3=Color3.fromRGB(178,194,211)
   elseif v.TextSize>=12 then
    v.Font=Enum.Font.GothamMedium v.TextColor3=Color3.fromRGB(240,246,252)
   end
  elseif v:IsA('TextButton') and v.Name~='AccordionHeader' then
   v.TextSize=math.max(v.TextSize,12) v.Font=Enum.Font.GothamMedium
   local grad=v:FindFirstChild('ModernDepth') or Instance.new('UIGradient')
   grad.Name='ModernDepth' grad.Rotation=90 grad.Color=ColorSequence.new(Color3.fromRGB(255,255,255),Color3.fromRGB(185,201,222)) grad.Parent=v
   local e=edge(v,Color3.fromRGB(96,127,145),.65)
   -- Keep existing functional signals and add lightweight visual feedback.
   table.insert(connections,v.MouseEnter:Connect(function() animate(e,{Transparency=.25}) end))
   table.insert(connections,v.MouseLeave:Connect(function() animate(e,{Transparency=.65}) end))
  elseif v:IsA('TextBox') then
   v.TextSize=math.max(v.TextSize,12)
   local e=edge(v,Color3.fromRGB(96,127,145),.65)
   table.insert(connections,v.Focused:Connect(function() animate(e,{Color=mint,Transparency=.1}) end))
   table.insert(connections,v.FocusLost:Connect(function() animate(e,{Color=Color3.fromRGB(96,127,145),Transparency=.65}) end))
  elseif v:IsA('Frame') and (v.Name:match('Group_') or v.Name=='SessionOverview') then
   local g=v:FindFirstChild('CardDepth') or Instance.new('UIGradient') g.Name='CardDepth' g.Rotation=110 g.Color=ColorSequence.new(Color3.fromRGB(255,255,255),Color3.fromRGB(170,192,216)) g.Parent=v
   edge(v,Color3.fromRGB(87,111,129),.6)
  end
 end
 -- Visibility is still controlled by the existing navigation; animate only the entering page.
 table.insert(connections,page:GetPropertyChangedSignal('Visible'):Connect(function()
  if page.Visible then
   page.Position=UDim2.fromOffset(100,270)
   animate(page,{Position=UDim2.fromOffset(100,260)},.3)
  end
 end))
end
-- Animate the session thumbnail on hover without changing card layout.
local m=u.sessionMetrics
if m then
 local image=m.preview
 table.insert(connections,image.MouseEnter:Connect(function() animate(image,{ImageColor3=Color3.fromRGB(225,255,242)},.3) end))
 table.insert(connections,image.MouseLeave:Connect(function() animate(image,{ImageColor3=Color3.new(1,1,1)},.3) end))
end
-- A short reveal when the window is reopened, with no continuously running animation loop.
table.insert(connections,u.shell:GetPropertyChangedSignal('Visible'):Connect(function()
 if u.shell.Visible and u.clipHost then u.clipHost.GroupTransparency=.12 animate(u.clipHost,{GroupTransparency=0},.22) end
end))
u.motionConnections=connections
u.motionReady=true

end,debug.traceback) if not ok then getgenv().FyrelithFullError="depth-motion: "..tostring(err) error(getgenv().FyrelithFullError) end end

