text(activity,'LIVE ACTIVITY',10,UDim2.fromOffset(16,12),UDim2.new(1,-32,0,20),muted)
local activityText=text(activity,'Waiting for updates…',12,UDim2.fromOffset(16,42),UDim2.new(1,-32,0,70)) activityText.TextWrapped=true activityText.TextYAlignment=Enum.TextYAlignment.Top
local inventory=new('Frame',scroll,{Size=UDim2.new(1,0,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundColor3=Color3.fromRGB(12,17,23),BorderSizePixel=0,LayoutOrder=3}) round(inventory,14)
new('UIPadding',inventory,{PaddingTop=UDim.new(0,15),PaddingBottom=UDim.new(0,16),PaddingLeft=UDim.new(0,16),PaddingRight=UDim.new(0,16)})
new('UIListLayout',inventory,{Padding=UDim.new(0,9),SortOrder=Enum.SortOrder.LayoutOrder})
local heading=text(inventory,'ITEMS GAINED',11,UDim2.new(),UDim2.new(1,0,0,26)) heading.LayoutOrder=0
local note=text(inventory,'New items observed since this session started.',10,UDim2.new(),UDim2.new(1,0,0,28),muted) note.TextWrapped=true note.LayoutOrder=1
local empty=text(inventory,'No new items yet. Automation is still being monitored.',12,UDim2.new(),UDim2.new(1,0,0,48),muted) empty.TextWrapped=true empty.LayoutOrder=2
local rows={}
local exit=new('TextButton',container,{Text='Back to game',Font=Enum.Font.GothamBold,TextSize=13,TextColor3=Color3.fromRGB(17,24,31),BackgroundColor3=Color3.fromRGB(223,234,243),Size=UDim2.new(1,0,0,46),Position=UDim2.new(0,0,1,-46),AutoButtonColor=true}) round(exit,12) exit.Activated:Connect(function() u.setBlackScreen(false) end)
local started=perf.started or os.clock()
local function update()
 local elapsed=math.max(0,math.floor(os.clock()-started))
 badge.Text=S.enabled and 'RUNNING' or 'PAUSED' badge.TextColor3=S.enabled and Color3.fromRGB(174,228,204) or Color3.fromRGB(238,204,151)
 clock.Text=string.format('%02d:%02d:%02d  •  %s',elapsed//3600,(elapsed//60)%60,elapsed%60,game.Players.LocalPlayer.DisplayName)
 local total=0 local count=0 local keys={}
 for key,value in pairs(perf.gained) do total+=value count+=1 table.insert(keys,key) end table.sort(keys)
 metricValues[1].Text=tostring(S.opened or 0) metricValues[2].Text=tostring(S.bought or 0) metricValues[3].Text=tostring(S.sold or 0) metricValues[4].Text=tostring(total)
 local m=u.sessionMetrics
 activityText.Text=tostring(S.buyStatus or 'Monitoring automation')..'\n'..tostring(S.obbyStatus or '')..'\n'..(m and m.ping.Text or '')..'   •   Errors '..tostring(S.errors or 0)
 empty.Visible=count==0
 for i,key in ipairs(keys) do
  local row=rows[key]
  if not row then
   local frame=new('Frame',inventory,{Size=UDim2.new(1,0,0,52),BackgroundColor3=Color3.fromRGB(21,28,36),BorderSizePixel=0}) round(frame,10)
   local name=text(frame,key:gsub(' / ','  ·  '),11,UDim2.fromOffset(12,6),UDim2.new(1,-87,1,-12)) name.TextWrapped=true
   local amount=text(frame,'',15,UDim2.new(1,-66,0,0),UDim2.new(0,54,1,0),Color3.fromRGB(174,228,204)) amount.TextXAlignment=Enum.TextXAlignment.Right amount.Font=Enum.Font.GothamBold
   row={frame=frame,value=amount} rows[key]=row
  end
  row.frame.LayoutOrder=i+2 row.value.Text='+'..tostring(perf.gained[key])
 end
end
local function fit()
 local narrow=container.AbsoluteSize.X<560
 metrics.Size=UDim2.new(1,0,0,narrow and 188 or 94)
 for i,card in ipairs(metrics:GetChildren()) do if card:IsA('Frame') then local columns=narrow and 2 or 4 local index=i-1 card.Size=UDim2.new(1/columns,-9,0,86) card.Position=UDim2.new((index%columns)/columns,0,0,math.floor(index/columns)*96) end end
end
container:GetPropertyChangedSignal('AbsoluteSize'):Connect(fit) fit()
overlay:GetPropertyChangedSignal('Enabled'):Connect(function() if overlay.Enabled then update() end end)
task.spawn(function() while S.running and overlay.Parent do if overlay.Enabled then update() end task.wait(1) end end)
