do local ok,err=xpcall(function() -- filter-item-images
local S=getgenv().BlueFarm local u=S.modernUI
local root=game.ReplicatedStorage.Shared.Core.Storage.Game
local libraries={}
for _,name in ipairs({'TokensLibrary','PotionsLibrary','VariantTokensLibrary'}) do local ok,value=pcall(require,root[name]) if ok then libraries[name]=value end end
local popup=u.shell:FindFirstChild('EventSelector')
assert(popup,'Event selector missing')
local list=popup.Dialog.Items
local function findImage(name)
 for _,lib in pairs(libraries) do local value=lib[name] if type(value)=='table' and type(value.Image)=='string' then return value.Image end end
end
local function add(row)
 if not row:IsA('TextButton') or not row.Name:match('^Choice_') then return end
 local name=row.Name:sub(8)
 local image=findImage(name)
 local images={}
 if image then images={image}
 elseif name=='rain' then images={findImage('Grade'),findImage('Trait'),findImage('LuckPotion')}
 elseif name=='variant' then images={findImage('Shadow'),findImage('Predator'),findImage('Halloween')} end
 if not images[1] then return end
 local existing=row:FindFirstChild('ItemArtwork') if existing then existing:Destroy() end
 local holder=Instance.new('Frame') holder.Name='ItemArtwork' holder.BackgroundTransparency=1 holder.Size=UDim2.fromOffset(48,48) holder.Position=UDim2.fromOffset(10,11) holder.ZIndex=row.ZIndex+1 holder.Parent=row
 for i,asset in ipairs(images) do
  local icon=Instance.new('ImageLabel') icon.Name='ItemImage' icon.BackgroundTransparency=1 icon.Image=asset icon.ScaleType=Enum.ScaleType.Fit icon.ZIndex=holder.ZIndex+i
  if #images==1 then icon.Size=UDim2.fromScale(1,1) icon.Position=UDim2.new()
  else icon.Size=UDim2.fromOffset(30,30) icon.Position=UDim2.fromOffset((i-1)*9,(i-1)*8) end
  icon.Parent=holder
 end
 for _,label in ipairs(row:GetChildren()) do
  if label:IsA('TextLabel') and label.Size.X.Offset~=44 then
   label.Position=UDim2.new(0,70,label.Position.Y.Scale,label.Position.Y.Offset)
   label.Size=UDim2.new(1,-134,0,label.Size.Y.Offset)
   label.TextTruncate=Enum.TextTruncate.AtEnd
  end
 end
end
for _,row in ipairs(list:GetChildren()) do add(row) end
if u.filterImageConnection then u.filterImageConnection:Disconnect() end
u.filterImageConnection=list.ChildAdded:Connect(function(row) task.defer(function() if row.Parent then add(row) end end) end)
u.filterImagesReady=true

end,debug.traceback) if not ok then getgenv().FyrelithFullError="filter-item-images: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- filter-polish
local S=getgenv().BlueFarm local u=S.modernUI
local popup=u.shell.EventSelector local dialog=popup.Dialog local list=dialog.Items
local Tween=game:GetService('TweenService')
local reference=u.pages.Setting:FindFirstChild('BindUIKey',true)
if u.filterPolishConnections then for _,c in ipairs(u.filterPolishConnections) do c:Disconnect() end end
local connections={} local rows=setmetatable({},{__mode='k'}) local updating=false
local function round(v,n) local c=v:FindFirstChildOfClass('UICorner') or Instance.new('UICorner',v) c.CornerRadius=UDim.new(0,n) end
local function depth(v,name,top,bottom,rotation)
 local g=v:FindFirstChild(name) or Instance.new('UIGradient') g.Name=name g.Color=ColorSequence.new(top,bottom) g.Rotation=rotation or 90 g.Parent=v return g
end
local function colors()
 local base=reference.BackgroundColor3
 return base,base:Lerp(Color3.fromRGB(100,115,135),.16),base:Lerp(Color3.new(0,0,0),.34)
end
local function render(row,animate)
 local state=rows[row] if not state or updating then return end updating=true
 local base,light,dark=colors() local selected=true
 local status=state.status if status then selected=status.Text=='ON' end
 local color=selected and base:Lerp(Color3.fromRGB(96,111,131),.22) or dark
 if state.hover then color=color:Lerp(Color3.new(1,1,1),.055) end
 if animate then Tween:Create(row,TweenInfo.new(.16,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{BackgroundColor3=color}):Play() else row.BackgroundColor3=color end
 if status then status.BackgroundColor3=selected and reference.TextColor3:Lerp(Color3.fromRGB(145,160,178),.25) or dark status.TextColor3=selected and Color3.fromRGB(15,22,30) or Color3.fromRGB(147,158,175) status.Font=Enum.Font.GothamBold status.TextSize=10 end
 updating=false
end
local function add(row)
 if not row:IsA('TextButton') or not row.Name:match('^Choice_') or rows[row] then return end
 round(row,14) row.AutoButtonColor=false
 depth(row,'FilterCardDepth',Color3.new(1,1,1),Color3.fromRGB(189,202,219),105)
 local status
 for _,label in ipairs(row:GetChildren()) do
  if label:IsA('TextLabel') then
   if label.Size.X.Offset==44 then status=label round(label,8)
   else label.TextColor3=label.TextSize>=13 and Color3.fromRGB(242,247,252) or Color3.fromRGB(156,173,194) end
  end
 end
 local holder=row:FindFirstChild('ItemArtwork')
 if holder then
  local backdrop=Instance.new('Frame') backdrop.Name='IconWell' backdrop.Size=UDim2.fromOffset(50,50) backdrop.Position=UDim2.fromOffset(9,10) backdrop.BackgroundColor3=Color3.fromRGB(11,16,24) backdrop.BackgroundTransparency=.32 backdrop.BorderSizePixel=0 backdrop.ZIndex=row.ZIndex backdrop.Parent=row round(backdrop,12)
 end
 rows[row]={hover=false,status=status}
 table.insert(connections,row.MouseEnter:Connect(function() rows[row].hover=true render(row,true) end))
 table.insert(connections,row.MouseLeave:Connect(function() rows[row].hover=false render(row,true) end))
 table.insert(connections,row:GetPropertyChangedSignal('BackgroundColor3'):Connect(function() if not updating then render(row,false) end end))
 if status then
  table.insert(connections,status:GetPropertyChangedSignal('Text'):Connect(function() render(row,false) end))
  table.insert(connections,status:GetPropertyChangedSignal('BackgroundColor3'):Connect(function() if not updating then render(row,false) end end))
 end
 render(row,false)
end
local function theme()
 local base,light,dark=colors()
 dialog.BackgroundColor3=dark
 depth(dialog,'FilterSurface',Color3.new(1,1,1),Color3.fromRGB(172,184,203),75)
 dialog.Search.BackgroundColor3=base:Lerp(Color3.fromRGB(48,60,77),.18) dialog.Search.TextXAlignment=Enum.TextXAlignment.Left
 round(dialog.Search,12)
 for _,b in ipairs(dialog:GetChildren()) do
  if b:IsA('TextButton') then
   b.BackgroundColor3=b.Name=='Done' and reference.TextColor3:Lerp(Color3.fromRGB(175,191,207),.2) or light
   b.TextColor3=b.Name=='Done' and Color3.fromRGB(16,24,32) or Color3.fromRGB(230,239,247)
   b.Font=Enum.Font.GothamBold round(b,10)
  end
 end
 for row in pairs(rows) do if row.Parent then render(row,false) end end
end
round(dialog,20)
popup.BackgroundTransparency=.18
for _,row in ipairs(list:GetChildren()) do add(row) end
table.insert(connections,list.ChildAdded:Connect(function(row) task.defer(function() if row.Parent then add(row) end end) end))
table.insert(connections,reference:GetPropertyChangedSignal('BackgroundColor3'):Connect(theme))
table.insert(connections,popup:GetPropertyChangedSignal('Visible'):Connect(function() if popup.Visible then theme() end end))
theme()
u.filterPolishConnections=connections
u.filterPolished=true

end,debug.traceback) if not ok then getgenv().FyrelithFullError="filter-polish: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- instant-travel-mode
local S=getgenv().BlueFarm local u=S.modernUI
local modes=u.pages.Travel:FindFirstChild('TravelModes',true)
assert(modes,'Travel mode buttons missing')
local function refresh()
 for _,name in ipairs({'TP','Tween'}) do
  local button=modes[name]
  button:SetAttribute('ThemeSelected',S.options.collectMode==name)
 end
 modes.TweenSpeed.Visible=S.options.collectMode=='Tween'
 modes.TPInterval.Visible=S.options.collectMode=='TP'
 modes.Size=UDim2.new(1,-6,0,S.options.collectMode=='Tween' and 132 or 94)
end
for _,name in ipairs({'TP','Tween'}) do
 local button=modes[name]
 for _,signal in ipairs({button.Activated,button.MouseButton1Click}) do for _,c in ipairs(getconnections(signal)) do c:Disconnect() end end
 -- Start on press, so touch and mouse both respond before release.
 button.InputBegan:Connect(function(input)
  if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then S.options.collectMode=name refresh() end
 end)
 button.Activated:Connect(function() S.options.collectMode=name refresh() end)
end
refresh()
u.instantTravelMode=true

end,debug.traceback) if not ok then getgenv().FyrelithFullError="instant-travel-mode: "..tostring(err) error(getgenv().FyrelithFullError) end end

do local ok,err=xpcall(function() -- control-animation
if getgenv().BlueFarm.mobileLite then return end
local u=getgenv().BlueFarm.modernUI
if u.controlAnimationConnections then for _,c in ipairs(u.controlAnimationConnections) do c:Disconnect() end end
local Tween=game:GetService('TweenService')
local gui=game.Players.LocalPlayer.PlayerGui.BlueFarmControls
for _,v in ipairs(gui:QueryDescendants('#SelectionMotion')) do v:Destroy() end
local connections={} local attached=setmetatable({},{__mode='k'})
local switchCount=0
local function connect(signal,fn) local c=signal:Connect(fn) table.insert(connections,c) end
local function animateSwitch(button)
 local switch=button:FindFirstChild('Switch') local thumb=switch and switch:FindFirstChild('Thumb')
 if not thumb then return end
 local visual=switch:FindFirstChild('AnimatedThumb') or thumb:Clone() visual.Name='AnimatedThumb' visual.Visible=true visual.Parent=switch
 thumb.Visible=false
 local movement,color
 local function move()
  if movement then movement:Cancel() end
  movement=Tween:Create(visual,TweenInfo.new(.2,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{Position=thumb.Position}) movement:Play()
 end
 connect(thumb:GetPropertyChangedSignal('Position'),move)
 connect(thumb:GetPropertyChangedSignal('BackgroundColor3'),function()
  if color then color:Cancel() end
  color=Tween:Create(visual,TweenInfo.new(.18),{BackgroundColor3=thumb.BackgroundColor3}) color:Play()
 end)
 switchCount+=1
end
local function attach(button)
 if not button:IsA('GuiButton') or attached[button] then return end
 attached[button]=true animateSwitch(button)
 local function obsolete(fn,depth)
  if depth>1 then return false end
  local ok,constants=pcall(debug.getconstants,fn)
  if ok then for _,value in ipairs(constants) do if value=='TapFeedback' or value=='SelectionMotion' or value=='PressScale' then return true end end end
  local success,ups=pcall(debug.getupvalues,fn)
  if success then for _,value in pairs(ups) do if type(value)=='function' and obsolete(value,depth+1) then return true end end end
  return false
 end
 for _,signal in ipairs({button.InputBegan,button.InputEnded,button.MouseLeave,button:GetAttributeChangedSignal('ThemeSelected')}) do
  for _,connection in ipairs(getconnections(signal)) do if connection.Function and obsolete(connection.Function,0) then connection:Disconnect() end end
 end
 for _,v in ipairs(button:GetChildren()) do if v.Name=='TapFeedback' or v.Name=='PressScale' or v.Name=='PressTint' then v:Destroy() end end
 local tint=Instance.new('Frame') tint.Name='PressTint' tint.BackgroundColor3=Color3.new(1,1,1) tint.BackgroundTransparency=1 tint.BorderSizePixel=0 tint.Size=UDim2.fromScale(1,1) tint.ZIndex=button.ZIndex+8 tint.Active=false tint.Parent=button
 local existing=button:FindFirstChildOfClass('UICorner') or button.Parent:FindFirstChildOfClass('UICorner')
 local corner=Instance.new('UICorner') corner.CornerRadius=existing and existing.CornerRadius or UDim.new(0,12) corner.Parent=tint
 local motion
 local function shade(alpha,time)
  if motion then motion:Cancel() end
  motion=Tween:Create(tint,TweenInfo.new(time,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),{BackgroundTransparency=alpha}) motion:Play()
 end
 connect(button.InputBegan,function(input)
  if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then shade(.92,.08) end
 end)
 connect(button.InputEnded,function(input)
  if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then shade(1,.18) end
 end)
 connect(button.MouseLeave,function() shade(1,.18) end)
